REPLACE INTO episodes (id, title, title_ko, place, npc, day_from, day_to, time_from, time_to, requires, summary, summary_ko, reward, energy, sort, tags) VALUES
  ('d1_bus', 'Good morning, neighbor', '이웃과 아침 인사', 'bus_stop', 'carl', 1, 1, '07:00', '09:30', NULL,
   'Your neighbor Carl is waiting for the bus too. Chat about your first day and find out how to pay the fare.', '이웃 칼도 버스를 기다리고 있습니다. 첫 출근 이야기를 나누고 버스 요금 내는 법을 알아보세요.',
   0, 0, 10, 'commute,neighbor,small-talk'),
  ('d1_coffee', 'Coffee on the way in', '출근길 커피 주문', 'coffee_cart', 'nina', 1, 5, '07:00', '10:30', NULL,
   'Order a latte at the coffee cart near the office: size, milk, name, and payment.', '회사 근처 커피 카트에서 라테를 주문하세요. 크기, 우유, 이름, 결제까지.',
   -5, 9, 20, 'food,order,coffee'),
                                                                                                                                       ('d1_badge', 'Picking up your badge', '출입증 받기', 'office_lobby', 'tom', 1, 1, '08:00', '10:30', NULL,
   'It is your first day. Introduce yourself at the front desk and get your badge.', '첫 출근 날입니다. 프런트에서 자기소개를 하고 출입증을 받으세요.',
   0, 0, 30, 'onboarding,office,intro'),
  ('d1_onboarding', 'Onboarding with Maya', '마야와 온보딩', 'office_manager', 'maya', 1, 1, '08:30', '12:00', 'd1_badge',
   'Meet your manager. Get your laptop, ask about access to the code, and learn what the team is building.', '매니저를 만납니다. 노트북을 받고, 코드 접근 권한을 묻고, 팀이 무엇을 만드는지 알아보세요.',
   0, 0, 40, 'onboarding,manager,office'),
  ('d1_standup', 'Your first standup', '첫 스탠드업 회의', 'office_meeting', 'priya', 1, 1, '09:30', '12:30', 'd1_onboarding',
   'The daily standup: say hello to the team, then share what you are doing today and your blockers.', '데일리 스탠드업: 팀에 인사하고, 오늘 할 일과 막힌 점(blocker)을 공유하세요.',
   0, 0, 45, 'meeting,standup'),
  ('d1_desk', 'Your desk and dev setup', '자리 안내와 개발 환경', 'office_desk_team', 'derek', 1, 1, '09:30', '17:30', 'd1_onboarding',
   'Meet Derek, your onboarding buddy. He shows you your desk and how the team works.', '온보딩 버디 데릭을 만납니다. 자리와 팀의 일하는 방식을 알려 줍니다.',
   0, 0, 50, 'coworker,dev,onboarding'),
  ('d1_lunch', 'Lunch at the diner', '다이너에서 점심', 'diner_counter', 'rosa', 1, 5, '11:30', '14:30', NULL,
   'Order a burger at the Sunny Side Diner: how you want it cooked, for here or to go, the check, and the tip.', '서니 사이드 다이너에서 버거를 주문하세요. 굽기, 먹고 갈지 포장할지, 계산서와 팁까지.',
   -20, 40, 60, 'food,diner,tipping'),
  ('d1_market', 'Checking out at the market', '마트 계산대에서', 'market_checkout', 'mike', 1, 5, '17:00', '22:00', NULL,
   'Pay for your groceries: the rewards card, paper or plastic, and the receipt.', '장 본 물건을 계산하세요. 적립 카드, 종이봉투냐 비닐봉지냐, 영수증까지.',
   0, 0, 70, 'shopping,market'),
  ('d2_code_review', 'Comments on your pull request', '풀 리퀘스트 리뷰 코멘트', 'office_desk_team', 'derek', 2, 2, '09:00', '17:30', NULL,
   'Derek reviewed your first pull request. Talk through his comments and agree on the next steps.', '데릭이 첫 풀 리퀘스트를 리뷰했습니다. 코멘트를 함께 보고 다음 할 일을 정하세요.',
   0, 0, 10, 'dev,code-review,feedback'),
  ('d2_reschedule', 'Moving a meeting', '회의 시간 옮기기', 'office_meeting', 'priya', 2, 2, '10:00', '12:59', NULL,
   'Priya wants to meet at one, but you already have an IT appointment. Move the meeting to two.', '프리야가 한 시에 만나자고 하지만 이미 IT 예약이 있습니다. 회의를 두 시로 옮기세요.',
   0, 0, 20, 'meeting,scheduling'),
  ('d2_it_laptop', 'My laptop keeps freezing', '노트북이 자꾸 멈춰요', 'office_it', 'sam', 2, 2, '12:30', '17:30', NULL,
   'Your laptop freezes when you run the tests. Explain the problem to Sam at the IT help desk.', '테스트를 돌리면 노트북이 멈춥니다. IT 헬프데스크의 샘에게 문제를 설명하세요.',
   0, 0, 30, 'it,support,office'),
  ('d3_one_on_one', 'First one-on-one', '첫 1:1 면담', 'office_manager', 'maya', 3, 3, '10:30', '13:00', NULL,
   'Your first 1:1 with Maya: how you are settling in, your priorities, and how you like to get feedback.', '마야와의 첫 1:1: 적응은 잘 하는지, 우선순위, 피드백을 어떻게 받고 싶은지.',
   0, 0, 10, 'manager,feedback,1:1'),
  ('d3_lunch', 'Taco lunch with Derek', '데릭과 타코 점심', 'office_desk_team', 'derek', 3, 3, '11:30', '13:30', NULL,
   'Derek invites you to lunch at a food truck. Accept, and make small talk about the weekend and Fairview.', '데릭이 푸드트럭 점심에 초대합니다. 수락하고 주말과 페어뷰에 대해 가볍게 이야기하세요.',
   -12, 35, 15, 'small-talk,lunch,food');

REPLACE INTO episodes (id, title, title_ko, place, npc, day_from, day_to, time_from, time_to, requires, summary, summary_ko, reward, energy, sort, tags) VALUES
  ('d3_planning', 'Sprint planning', '스프린트 플래닝', 'office_meeting', 'priya', 3, 3, '13:30', '16:30', NULL,
   'Your first sprint planning: learn what a story point means, estimate a ticket, and take on work.', '첫 스프린트 플래닝: 스토리 포인트의 뜻을 배우고, 티켓을 추정하고, 일을 맡으세요.',
   0, 0, 20, 'meeting,planning,agile'),
  ('d4_deadline', 'Pushing the deadline', '마감 미루기', 'office_meeting', 'priya', 4, 4, '10:15', '15:00', NULL,
   'The refund bug is harder than expected. Tell Priya early, ask for more time, and agree on a smaller scope.', '환불 버그가 생각보다 어렵습니다. 프리야에게 미리 알리고, 시간을 더 요청하고, 범위를 줄이는 데 합의하세요.',
   0, 0, 10, 'meeting,negotiation,planning'),
                                                                            ('d4_benefits', 'HR paperwork and benefits', '인사 서류와 복리후생', 'office_hr', 'linda', 4, 4, '12:30', '17:30', NULL,
   'Finish your new-hire paperwork with Linda: the W-4 tax form, a health insurance plan, and the 401(k).', '린다와 신입 서류를 마무리하세요. W-4 세금 양식, 건강보험 플랜, 401(k)까지.',
   0, 0, 20, 'hr,benefits,money'),
  ('d4_pto', 'Asking about time off', '휴가 문의하기', 'office_manager', 'maya', 4, 4, '13:30', '18:00', NULL,
   'Your friend is getting married next month. Ask Maya how PTO and sick days work.', '다음 달에 친구가 결혼합니다. 마야에게 유급휴가(PTO)와 병가가 어떻게 되는지 물어보세요.',
   0, 0, 30, 'hr,pto,manager'),
  ('d5_demo', 'Sprint demo and retro', '스프린트 데모와 회고', 'office_meeting', 'priya', 5, 5, '10:15', '14:00', NULL,
   'Show your card payment fix at the sprint demo, then share what went well and what could be better.', '스프린트 데모에서 카드 결제 수정을 보여 주고, 잘된 점과 개선할 점을 나누세요.',
   0, 0, 10, 'meeting,demo,retro'),
  ('d5_paystub', 'Reading your pay stub', '급여명세서 읽기', 'office_hr', 'linda', 5, 5, '12:30', '17:30', NULL,
   'Payday! Your first paycheck arrived by direct deposit, but it is smaller than you thought. Linda explains the pay stub.', '급여일입니다! 첫 급여가 계좌로 들어왔는데 생각보다 적습니다. 린다가 급여명세서를 설명해 줍니다.',
   0, 0, 20, 'hr,payday,money'),
  ('d5_happy_hour', 'Happy hour invite', '해피아워 초대', 'office_desk_team', 'derek', 5, 5, '15:00', '18:30', NULL,
   'Derek invites you to Friday happy hour. Decline politely, ask for a rain check, and wish him a good weekend.', '데릭이 금요일 해피아워에 초대합니다. 정중히 거절하고, 다음을 기약하고, 좋은 주말을 빌어 주세요.',
   0, 0, 30, 'small-talk,social,invitation');

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d1_bus', 1, 'carl',
   'It is your first Monday in Fairview. Your neighbor Carl, who also owns your building, is waiting at the bus stop.', '페어뷰에서 맞는 첫 월요일입니다. 이웃이자 건물 주인인 칼이 버스 정류장에서 기다리고 있습니다.',
   'Well, look who''s up early! Heading into work?', 'Say yes, and tell him it is your first day at a new job.', '그렇다고 하고, 새 직장 첫 출근이라고 말하세요.',
   '[{"all":["first day"]},{"all":["new job"]},{"all":["start","today"]}]',
   'Yeah, it''s my first day at my new job.',
   '["Yeah, I just got back from vacation.","No, I''m going to the grocery store.","I''d like a medium coffee, please."]',
                                                                                                                                                             '["Tell him today is your first day.","Key words: first day, new job"]', '["오늘이 첫 출근이라고 말하세요.","핵심 단어: first day, new job"]',
   'carl', 'No kidding! Congrats, kid.', '정말? 축하해!'),
  ('d1_bus', 2, 'carl',
   'Carl folds his newspaper and turns to you.', '칼이 신문을 접고 당신 쪽으로 돌아섭니다.',
   'So where''s the new gig?', 'Tell him you are a software developer at Lakeside Labs.', '레이크사이드 랩스에서 소프트웨어 개발자로 일한다고 말하세요.',
   '[{"all":["lakeside"]},{"all":["developer"]},{"all":["software"]},{"all":["engineer"]}]',
   'It''s at Lakeside Labs downtown. I''m a software developer.',
   '["It''s on the third floor, next to the kitchen.","I''m from out of town, actually.","It''s supposed to rain later today."]',
   '["Say the company name and your job.","Key words: Lakeside Labs, developer"]', '["회사 이름과 직업을 말하세요.","핵심 단어: Lakeside Labs, developer"]',
   'carl', 'Oh, the tech place by the river. Fancy!', '아, 강가에 있는 그 IT 회사. 멋지네!'),
  ('d1_bus', 3, 'carl',
   'You have never taken this bus before.', '이 버스를 타는 건 처음입니다.',
   'The Number 12 should be here any minute. You got your fare?', 'Ask how much it is and whether you can pay by card.', '얼마인지, 카드로 낼 수 있는지 물어보세요.',
   '[{"all":["how much"]},{"all":["pay"],"any":["card","tap","phone","cash"]},{"all":["exact change"]}]',
   'How much is it? Can I just tap my card?',
   '["How far is it to the airport?","Can I get a receipt, please?","Is this seat taken?"]',
   '["Ask about the price and paying with a card.","Key words: how much, card"]', '["가격과 카드 결제에 대해 물어보세요.","핵심 단어: how much, card"]',
   'carl', 'Two fifty. Just tap your card on the reader when you get on.', '2달러 50센트. 탈 때 단말기에 카드를 대면 돼.'),
  ('d1_bus', 4, 'carl',
   'The bus pulls up and the doors open. Carl waves you ahead.', '버스가 서고 문이 열립니다. 칼이 먼저 타라고 손짓합니다.',
   'Here it comes. After you! Have a good one.', 'Thank him and wish him a good day too.', '고맙다고 하고, 그에게도 좋은 하루 보내라고 말하세요.',
   '[{"any":["thanks","thank"]},{"all":["you too"]},{"all":["good day"]}]',
   'Thanks, Carl! You too.',
   '["I''ll take the stairs instead.","Could you move it to two o''clock?","Nice to meet you. Are you new here?"]',
   '["Say thanks, and return the wish.","Key words: thanks, you too"]', '["고맙다고 하고 같은 인사를 돌려주세요.","핵심 단어: thanks, you too"]',
   'carl', 'Knock ''em dead, kid!', '가서 한 방 보여 줘!'),
  ('d1_coffee', 1, 'nina',
   'A small coffee cart stands on the corner of Lake Avenue. The barista smiles at you.', '레이크 애비뉴 모퉁이에 작은 커피 카트가 있습니다. 바리스타가 웃으며 맞이합니다.',
   'Morning! What can I get started for you?', 'Order a medium latte.', '라테 미디엄 사이즈를 주문하세요.',
   '[{"all":["latte"]},{"all":["coffee"]},{"all":["cappuccino"]}]',
   'Can I get a medium latte, please?',
   '["Can I get the check, please?","I''d like a window seat, please.","Could I get a paper bag, please?"]',
   '["Order with \\"Can I get a …, please?\\"","Key words: medium, latte"]', '["\\"Can I get a …, please?\\"로 주문하세요.","핵심 단어: medium, latte"]',
   'nina', 'You got it. One medium latte.', '알겠어요. 라테 미디엄 하나.'),
  ('d1_coffee', 2, 'nina',
   'Nina reaches for the milk.', '니나가 우유 쪽으로 손을 뻗습니다.',
   'Any milk preference? We''ve got whole, skim, oat, and almond.', 'Ask for oat milk.', '귀리 우유로 달라고 하세요.',
   '[{"any":["oat","almond","whole","skim","regular"]}]',
   'Oat milk, please.',
   '["For here, please.","Just the bill, thanks.","Aisle seven, I think."]',
   '["Name the milk you want and add \\"please\\".","Key words: oat milk"]', '["원하는 우유 이름에 please를 붙이세요.","핵심 단어: oat milk"]',
   'nina', 'Oat milk. Great choice.', '귀리 우유. 좋은 선택이에요.');

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d1_coffee', 3, 'nina',
   'She picks up a paper cup and a marker.', '그녀가 종이컵과 마커를 집어 듭니다.',
   'And what''s the name for the order?', 'Tell her your name.', '이름을 말하세요.',
   '[{"all":["name"]},{"all":["it is"]},{"all":["i am"]},{"any":["jun"]}]',
   'It''s Jun. J-U-N.',
   '["The bus stop is on Maple Street.","Medium, please.","Here is a five-dollar bill."]',
   '["Say \\"It''s …\\" with your name. You can spell it.","Key words: It''s + your name"]', '["\\"It''s …\\" 뒤에 이름을 말하세요. 철자를 불러 줘도 좋아요.","핵심 단어: It''s + 이름"]',
   'nina', 'Got it!', '알겠어요!'),
  ('d1_coffee', 4, 'nina',
                                                                                                                                                                             'The card reader lights up.', '카드 단말기에 불이 들어옵니다.',
   'That''ll be four seventy-five. Card or cash?', 'Say you will pay by card.', '카드로 내겠다고 하세요.',
   '[{"any":["card","tap","cash"]}]',
   'Card, please. I''ll just tap.',
   '["I''ll have the pancakes.","Sorry, it''s my first day.","Two fifty, I think."]',
   '["Answer her question: card or cash.","Key words: card"]', '["카드인지 현금인지 답하세요.","핵심 단어: card"]',
   'nina', 'Perfect. The screen will ask about a tip. Totally up to you! Here''s your latte.', '좋아요. 화면에 팁을 물어볼 거예요. 전적으로 마음대로 하세요! 라테 나왔어요.'),
  ('d1_badge', 1, 'tom',
   'You walk up to the front desk on your first morning at Lakeside Labs.', '레이크사이드 랩스 첫 출근 아침, 프런트 데스크로 다가갑니다.',
   'Hi there! How can I help you?', 'Introduce yourself and say it is your first day.', '자기소개를 하고 오늘이 첫날이라고 말하세요.',
   '[{"all":["first day"]},{"all":["start","today"]},{"all":["new","developer"]}]',
   'Hi, I''m Jun. It''s my first day here. I''m joining the platform team as a developer.',
   '["Hi, I''m looking for the bus stop.","Can I get a large coffee, please?","I''d like to check in for my flight."]',
   '["Say: It''s my first day.","Key words: first day"]', '["It''s my first day.라고 말해 보세요.","핵심 단어: first day"]',
   'tom', 'Welcome aboard! You must be the new developer.', '환영해요! 새로 온 개발자군요.'),
  ('d1_badge', 2, 'tom',
   'Tom pulls up a form on his screen and points a small camera at you.', '톰이 화면에 양식을 띄우고 작은 카메라를 당신 쪽으로 돌립니다.',
   'I just need to see a photo ID for the badge.', 'Hand him your ID and say "here you go".', '신분증을 건네며 "여기 있어요"라고 하세요.',
   '[{"all":["here you go"]},{"all":["here it is"]},{"all":["here you are"]},{"any":["license","passport"]}]',
   'Sure, here you go. It''s my driver''s license.',
   '["Sure, I''ll have a large coffee.","Sorry, I''m just looking.","It''s on the second floor."]',
   '["Use the phrase for handing something over.","Key words: here you go"]', '["물건을 건넬 때 쓰는 표현을 쓰세요.","핵심 단어: here you go"]',
   'tom', 'Thanks. Okay, smile! … Perfect. Here''s your badge.', '고마워요. 자, 웃어요! … 좋아요. 출입증 여기 있어요.'),
  ('d1_badge', 3, 'tom',
   'The badge has your photo on it. It looks a little surprised.', '출입증에 당신 사진이 있습니다. 좀 놀란 표정이네요.',
   'Tap it on the reader by the glass doors. It''ll get you into the building and up to three.', 'Ask what you should do if you forget your badge.', '출입증을 깜빡하면 어떻게 해야 하는지 물어보세요.',
   '[{"all":["forget"]},{"all":["lose"]},{"all":["what if"]}]',
   'Got it. What should I do if I forget my badge?',
   '["Got it. What should I do if the bus is late?","Got it. Where can I park my bike?","Got it. Is the cafeteria open now?"]',
   '["Ask: What should I do if I …?","Key words: forget, badge"]', '["What should I do if I …?로 물어보세요.","핵심 단어: forget, badge"]',
   'tom', 'Just come see me. I''ll give you a temporary one for the day.', '저한테 오면 돼요. 그날 쓸 임시 출입증을 드릴게요.'),
  ('d1_badge', 4, 'tom',
   'Tom points past a row of plants.', '톰이 화분들 너머를 가리킵니다.',
   'Maya''s expecting you on three. The elevators are right past the plants, on your left.', 'Thank him.', '고맙다고 하세요.',
   '[{"any":["thanks","thank","appreciate"]}]',
   'Thanks so much, Tom. I appreciate it.',
   '["Sorry, I''m in a hurry.","No, I''ll take the stairs.","Could I get that to go?"]',
   '["Say thank you, maybe with \\"I appreciate it.\\"","Key words: thanks, appreciate"]', '["고맙다고 하세요. \\"I appreciate it.\\"을 덧붙여도 좋아요.","핵심 단어: thanks, appreciate"]',
   'tom', 'Anytime. Have a great first day!', '언제든지요. 좋은 첫날 보내요!');

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d1_onboarding', 1, 'maya',
   'Maya waves you into her office. There is a box with a new laptop on her desk.', '마야가 사무실로 들어오라고 손짓합니다. 책상에 새 노트북 상자가 있습니다.',
   'Hey, you made it! I''m Maya, your manager. How was the commute?', 'Say it was easy and that you took the bus.', '버스를 타고 왔는데 수월했다고 말하세요.',
   '[{"all":["bus"]},{"any":["easy","fine","smooth","not bad","pretty good"]}]',
   'Not bad at all. I took the bus, and it was pretty easy.',
   '["I''m allergic to peanuts, actually.","I''d like to return this, please.","It''s my neighbor''s car."]',
                                                                                                                                                                                                                      '["Say how it went and how you came.","Key words: bus, easy"]', '["어땠는지, 무엇을 타고 왔는지 말하세요.","핵심 단어: bus, easy"]',
   'maya', 'Good to hear. Parking downtown is a nightmare.', '다행이네요. 시내 주차는 악몽이거든요.'),
  ('d1_onboarding', 2, 'maya',
   'She slides the laptop box across the desk, along with a monitor cable and a headset.', '그녀가 노트북 상자와 모니터 케이블, 헤드셋을 건넵니다.',
   'So, here is your laptop, a monitor, and a headset. IT already set up your email.', 'Thank her and ask when you will get access to the code repository.', '고맙다고 하고, 코드 저장소 접근 권한은 언제 받는지 물어보세요.',
   '[{"all":["access"]},{"any":["repo","repository","codebase"]}]',
   'Great, thanks. When will I get access to the code repository?',
   '["Great, thanks. Can I get that to go?","Great, thanks. When is the next bus?","Great, thanks. Is it going to rain today?"]',
   '["Ask \\"When will I get access to …?\\"","Key words: access, repository"]', '["\\"When will I get access to …?\\"로 물어보세요.","핵심 단어: access, repository"]',
   'maya', 'Derek will add you today. He''s your onboarding buddy.', '데릭이 오늘 추가해 줄 거예요. 그가 온보딩 버디예요.'),
  ('d1_onboarding', 3, 'maya',
   'Maya opens a slide with the team photo.', '마야가 팀 사진이 있는 슬라이드를 엽니다.',
   'You''ll be on the Payments team with Derek and Priya. Any questions about the team?', 'Ask what the team is working on right now.', '팀이 지금 무슨 일을 하고 있는지 물어보세요.',
   '[{"all":["working on"]},{"all":["what","team"],"any":["building","doing","project"]}]',
   'What''s the team working on right now?',
   '["What time does the diner close?","Where do you usually buy groceries?","How long have you lived in Fairview?"]',
   '["Ask \\"What is the team working on …?\\"","Key words: working on"]', '["\\"What is the team working on …?\\"으로 물어보세요.","핵심 단어: working on"]',
   'maya', 'We''re rebuilding the checkout flow for our retail clients. Big project, fun stuff.', '소매업 고객들을 위해 결제 흐름을 다시 만들고 있어요. 큰 프로젝트인데 재밌어요.'),
  ('d1_onboarding', 4, 'maya',
   'She closes the laptop and smiles.', '그녀가 노트북을 덮고 웃습니다.',
   'Anyway, that''s a lot for day one. Let me know if you have any questions, okay? My door''s always open.', 'Thank her and say you will.', '고맙다고 하고 그러겠다고 말하세요.',
   '[{"any":["thanks","thank","will do","sounds good","appreciate"]}]',
   'Thanks, Maya. I will. I really appreciate it.',
   '["No, I''ll have the soup instead.","Sorry, I didn''t catch the bus number.","Paper, please."]',
   '["Say thanks, and \\"I will.\\"","Key words: thanks, I will"]', '["고맙다고 하고 \\"I will.\\"이라고 하세요.","핵심 단어: thanks, I will"]',
   'maya', 'Great. Go find Derek. He sits by the window.', '좋아요. 데릭을 찾아가 봐요. 창가에 앉아요.'),
  ('d1_standup', 1, 'priya',
   'Six people stand around a screen in the meeting room. Priya, the product manager, is running the meeting.', '회의실 화면 앞에 여섯 명이 서 있습니다. 프로덕트 매니저 프리야가 회의를 진행합니다.',
   'Okay, let''s get started. Oh, we have someone new! Want to say a quick hello?', 'Introduce yourself briefly to the team.', '팀에 짧게 자기소개를 하세요.',
   '[{"all":["developer"]},{"all":["joined"]},{"all":["new"],"any":["team","here","join"]},{"all":["first day"]}]',
   'Hi, everyone. I''m Jun. I just joined as a developer. Excited to be here!',
   '["Hi, everyone. I''ll have the club sandwich.","Hi, everyone. Is this seat taken?","Hi, everyone. Can I pay by card?"]',
   '["Say your name and your role, and that you just joined.","Key words: just joined, developer"]', '["이름과 역할, 막 합류했다는 것을 말하세요.","핵심 단어: just joined, developer"]',
   'priya', 'Welcome! We''re so happy to have you.', '환영해요! 와 줘서 정말 기뻐요.');

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d1_standup', 2, 'priya',
   'Everyone else has already said what they did yesterday. Now it is your turn.', '다른 사람들은 어제 한 일을 이미 말했습니다. 이제 당신 차례입니다.',
   'The format is yesterday, today, and blockers. Since it''s your first day, just tell us: what''s on your plate today?', 'Say that today you are setting up your laptop and dev environment.', '오늘은 노트북과 개발 환경을 세팅한다고 말하세요.',
   '[{"any":["setting up","set up","setup","install","installing"]}]',
   'Today I''m setting up my laptop and my dev environment.',
   '["Yesterday I went to the grocery store.","Today is Monday, I think.","I''m free on Saturday afternoon."]',
                                                                                                                                                  '["Start with \\"Today I''m …ing\\".","Key words: today, setting up"]', '["\\"Today I''m …ing\\"로 시작하세요.","핵심 단어: today, setting up"]',
   'priya', 'Perfect. That''s exactly what day one should look like.', '좋아요. 첫날은 딱 그래야죠.'),
  ('d1_standup', 3, 'priya',
   'Priya looks at you over her laptop.', '프리야가 노트북 너머로 당신을 봅니다.',
   'Any blockers?', 'Say you do not have access to the repository yet.', '아직 저장소 접근 권한이 없다고 말하세요.',
   '[{"all":["access"]},{"any":["permission","permissions"]},{"all":["waiting","repo"]}]',
   'Just one. I don''t have access to the repository yet.',
   '["Just one. I don''t have a car yet.","Just one. I don''t like cold brew.","Just one. The bus was a little late."]',
   '["Say what you do not have yet.","Key words: access, yet"]', '["아직 무엇이 없는지 말하세요.","핵심 단어: access, yet"]',
   'priya', 'Derek, can you help with that after standup? … Great, he says yes.', '데릭, 스탠드업 끝나고 그거 도와줄 수 있어요? … 좋아요, 된대요.'),
  ('d1_standup', 4, 'priya',
   'The meeting took twelve minutes. People start to leave.', '회의는 12분 걸렸습니다. 사람들이 나가기 시작합니다.',
   'That''s it for today. Short and sweet. Thanks, everyone!', 'Ask Priya if standup is every day at ten.', '스탠드업이 매일 열 시인지 프리야에게 물어보세요.',
   '[{"all":["every day"]},{"all":["everyday"]},{"all":["every","morning"]},{"all":["daily"]}]',
   'Thanks! Is standup every day at ten?',
   '["Thanks! Is the diner open on Sundays?","Thanks! Is the bus free on weekends?","Thanks! Is there a gym in the building?"]',
   '["Ask with \\"Is standup every …?\\"","Key words: every day, ten"]', '["\\"Is standup every …?\\"로 물어보세요.","핵심 단어: every day, ten"]',
   'priya', 'Every weekday at ten, fifteen minutes max. See you tomorrow!', '평일 매일 열 시, 길어야 15분이에요. 내일 봐요!'),
  ('d1_desk', 1, 'derek',
   'A man in a hoodie looks up from two monitors by the window.', '창가에서 모니터 두 대를 보던 후드티 차림의 남자가 고개를 듭니다.',
   'Hey! You must be the new hire. Derek. Welcome to the team!', 'Introduce yourself and say it is nice to meet him.', '자기소개를 하고 만나서 반갑다고 하세요.',
   '[{"all":["nice to meet"]},{"all":["good to meet"]},{"all":["pleasure"]},{"all":["great to meet"]}]',
   'Hi, I''m Jun. Nice to meet you, Derek.',
   '["Hi, I''d like a table for one.","Hi, is this the line for security?","Hi, I''m just browsing, thanks."]',
   '["Say your name and \\"Nice to meet you.\\"","Key words: nice to meet you"]', '["이름을 말하고 \\"Nice to meet you.\\"라고 하세요.","핵심 단어: nice to meet you"]',
   'derek', 'Likewise. So this is your desk, right next to mine.', '저도요. 여기가 당신 자리예요, 제 바로 옆.'),
  ('d1_desk', 2, 'derek',
   'Your monitor is already plugged in. A sticky note says "Welcome!"', '모니터는 이미 연결돼 있습니다. 포스트잇에 "Welcome!"이라고 쓰여 있습니다.',
   'Have you set up your dev environment yet?', 'Say not yet, and ask if there is a setup guide.', '아직이라고 하고, 설치 가이드가 있는지 물어보세요.',
   '[{"any":["guide","readme","docs","documentation","instructions","wiki"]}]',
   'Not yet. Is there a setup guide I can follow?',
   '["Not yet. Is there a bus that goes downtown?","Not yet. Is the diner open for lunch?","Not yet. Do you know a good dentist?"]',
   '["Ask \\"Is there a … I can follow?\\"","Key words: setup guide"]', '["\\"Is there a … I can follow?\\"로 물어보세요.","핵심 단어: setup guide"]',
   'derek', 'Yep, it''s in the README. Clone the repo, run the setup script, and go grab a coffee. It takes a while.', '네, README에 있어요. 저장소를 클론하고 설치 스크립트를 돌린 다음 커피 한 잔 하고 와요. 좀 걸려요.');

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d1_desk', 3, 'derek',
   'The setup script starts printing hundreds of lines.', '설치 스크립트가 수백 줄을 쏟아내기 시작합니다.',
   'If the tests fail on your machine, don''t worry. It happens to everybody.', 'Ask who you should ask if you get stuck.', '막히면 누구에게 물어봐야 하는지 물어보세요.',
   '[{"all":["stuck"]},{"all":["who"],"any":["ask","help","contact"]}]',
   'Good to know. Who should I ask if I get stuck?',
   '["Good to know. Where should I sit for lunch?","Good to know. When is payday?","Good to know. How much is the bus fare?"]',
   '["Use \\"get stuck\\" (can''t move forward).","Key words: who, stuck"]', '["get stuck(막히다)을 써 보세요.","핵심 단어: who, stuck"]',
                                                                                                                    'derek', 'Just ping me on chat. Seriously, no question is too dumb.', '채팅으로 그냥 불러요. 진짜로, 멍청한 질문은 없어요.'),
  ('d1_desk', 4, 'derek',
   'Derek opens a pull request on his screen to show you.', '데릭이 보여 주려고 화면에 풀 리퀘스트를 엽니다.',
   'We push code through pull requests. I''ll review your first one. Sound good?', 'Agree and thank him.', '좋다고 하고 고맙다고 하세요.',
   '[{"any":["sounds good","sounds great","perfect","great","awesome","okay","ok","sure","thanks","thank"]}]',
   'Sounds good. Thanks for your help, Derek.',
   '["No, I''d rather take the stairs.","I''m allergic to shellfish.","Could you ring me up?"]',
   '["Answer \\"Sound good?\\" with the same words.","Key words: sounds good, thanks"]', '["\\"Sound good?\\"에 같은 말로 답하세요.","핵심 단어: sounds good, thanks"]',
   'derek', 'Anytime. Welcome aboard, for real.', '언제든지요. 진심으로 환영해요.'),
  ('d1_lunch', 1, 'rosa',
   'The diner smells like coffee and bacon. A server with a pencil behind her ear waves you to the counter.', '다이너에 커피와 베이컨 냄새가 납니다. 귀에 연필을 꽂은 종업원이 카운터로 오라고 손짓합니다.',
   'Hi, hon! Just one today? Sit anywhere you like. What can I get you?', 'Order a cheeseburger.', '치즈버거를 주문하세요.',
   '[{"any":["burger","cheeseburger","sandwich","pancakes","soup","salad"]}]',
   'Can I get a cheeseburger, please?',
   '["Can I get a medium latte, please?","Can I get my badge, please?","Can I get a window seat, please?"]',
   '["Order with \\"Can I get a …?\\"","Key words: cheeseburger"]', '["\\"Can I get a …?\\"로 주문하세요.","핵심 단어: cheeseburger"]',
   'rosa', 'Sure thing.', '그럼요.'),
  ('d1_lunch', 2, 'rosa',
   'Rosa writes on her notepad.', '로사가 수첩에 적습니다.',
   'How would you like that cooked?', 'Say medium.', '미디엄으로 해 달라고 하세요.',
   '[{"any":["medium","well done","rare","medium rare","medium well"]}]',
   'Medium, please.',
   '["Oat milk, please.","Paper, please.","Aisle three, please."]',
   '["Burgers can be rare, medium, or well done.","Key words: medium"]', '["버거는 rare, medium, well done으로 익힙니다.","핵심 단어: medium"]',
   'rosa', 'Medium, you got it.', '미디엄, 알겠어요.'),
  ('d1_lunch', 3, 'rosa',
   'She taps the pencil on the pad.', '그녀가 연필로 수첩을 톡톡 칩니다.',
   'Comes with fries or a side salad. And is that for here or to go?', 'Choose fries and say it is for here.', '감자튀김을 고르고 여기서 먹고 간다고 하세요.',
   '[{"all":["for here"]},{"all":["to go"]}]',
   'Fries, please. And it''s for here.',
   '["Salad, please. And no, I''m not from here.","Fries, please. And it''s my first day.","Fries, please. And I''ll pay by card."]',
   '["Answer both questions: side, and for here or to go.","Key words: fries, for here"]', '["두 질문 모두 답하세요: 사이드, 그리고 먹고 갈지 포장할지.","핵심 단어: fries, for here"]',
   'rosa', 'It''ll be right out, hon.', '금방 나와요.'),
  ('d1_lunch', 4, 'rosa',
   'You finish the burger. It was really good.', '버거를 다 먹었습니다. 정말 맛있었어요.',
   'How was everything? Can I get you anything else?', 'Say it was great and ask for the check.', '맛있었다고 하고 계산서를 달라고 하세요.',
   '[{"all":["check"]},{"all":["bill"]}]',
   'It was great, thanks. Could I get the check, please?',
   '["It was great, thanks. Could I get a bigger desk?","It was great, thanks. Could I get a seat on the bus?","It was great, thanks. Could I see a photo ID?"]',
   '["In the US you ask for \\"the check\\".","Key words: check"]', '["미국에서는 계산서를 check라고 합니다.","핵심 단어: check"]',
   'rosa', 'Here you go, hon. You can pay me right here.', '여기 있어요. 여기서 바로 계산하면 돼요.');

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d1_lunch', 5, 'rosa',
   'The check says $16.50 with tax. You have a twenty-dollar bill.', '계산서에는 세금 포함 16.50달러라고 적혀 있습니다. 20달러 지폐가 있습니다.',
   'Sixteen fifty. Whenever you are ready.', 'Give her the twenty and tell her to keep the change as a tip.', '20달러를 주고 거스름돈은 팁으로 가지라고 하세요.',
   '[{"all":["keep the change"]},{"any":["tip"]}]',
   'Here''s a twenty. Keep the change.',
   '["Here''s my badge. Keep it safe.","Here''s my ID. It''s a driver''s license.","Here''s the bus. Let''s go."]',
                                                                                                                                                                                                                                                                                  '["Tell her she can keep the rest of the money.","Key words: keep the change"]', '["남는 돈은 가져도 된다고 말하세요.","핵심 단어: keep the change"]',
   'rosa', 'Aw, thank you, hon! Come back and see us.', '어머, 고마워요! 또 와요.'),
  ('d1_market', 1, 'mike',
   'You put your groceries on the belt at Fairview Market. The cashier starts scanning.', '페어뷰 마켓 계산대 벨트에 물건을 올려놓습니다. 계산원이 바코드를 찍기 시작합니다.',
   'Hey there. Did you find everything okay?', 'Say yes, you found everything.', '네, 다 찾았다고 말하세요.',
   '[{"any":["yes","yeah","yep"]},{"all":["found everything"]},{"all":["found it all"]}]',
   'Yeah, I found everything, thanks.',
   '["No, I''m here for the standup.","I''d like to check in, please.","Could I get the check, please?"]',
   '["Say yes and repeat \\"found everything\\".","Key words: yeah, found everything"]', '["네라고 하고 \\"found everything\\"을 반복하세요.","핵심 단어: yeah, found everything"]',
   'mike', 'Great.', '다행이네요.'),
  ('d1_market', 2, 'mike',
   'Mike points at a sign by the register.', '마이크가 계산대 옆 안내판을 가리킵니다.',
   'Do you have our rewards card?', 'Say no, and ask if it is free to sign up.', '없다고 하고, 가입이 무료인지 물어보세요.',
   '[{"all":["free"]},{"all":["sign up"]},{"all":["how","join"]},{"all":["cost"]}]',
   'No, I don''t. Is it free to sign up?',
   '["No, I don''t. Is there a gym nearby?","No, I don''t. Is it going to rain?","No, I don''t. Is Maya in today?"]',
   '["Ask if signing up costs money.","Key words: free, sign up"]', '["가입에 돈이 드는지 물어보세요.","핵심 단어: free, sign up"]',
   'mike', 'Totally free. Next time just punch in your phone number, and you''ll get the sale prices.', '완전 무료예요. 다음에 전화번호만 누르면 할인가로 살 수 있어요.'),
  ('d1_market', 3, 'mike',
   'He holds up two kinds of bags.', '그가 두 종류의 봉투를 들어 보입니다.',
   'Paper or plastic?', 'Say paper is fine.', '종이봉투면 된다고 하세요.',
   '[{"any":["paper","plastic","own bag","my bag"]}]',
   'Paper is fine, thanks.',
   '["Medium, please.","For here, please.","Oat milk, thanks."]',
   '["Choose one of the two.","Key words: paper"]', '["둘 중 하나를 고르세요.","핵심 단어: paper"]',
   'mike', 'Paper it is. Bags are ten cents each, just so you know.', '종이로 할게요. 참고로 봉투는 하나에 10센트예요.'),
  ('d1_market', 4, 'mike',
   'The screen shows the total.', '화면에 합계가 나옵니다.',
   'Your total''s twenty-three eighty-nine. Go ahead and insert or tap whenever you''re ready.', 'Pay, and ask him to put the receipt in the bag.', '계산하고, 영수증은 봉투에 넣어 달라고 하세요.',
   '[{"all":["receipt"]}]',
   'Thanks. Could you put the receipt in the bag?',
   '["Thanks. Could you put me on the waitlist?","Thanks. Could you move the meeting to two?","Thanks. Could you add me to the repo?"]',
   '["Ask \\"Could you put … in the bag?\\"","Key words: receipt, bag"]', '["\\"Could you put … in the bag?\\"로 부탁하세요.","핵심 단어: receipt, bag"]',
   'mike', 'You got it. Have a good night!', '알겠어요. 좋은 밤 보내요!'),
  ('d2_code_review', 1, 'derek',
   'Derek rolls his chair over to your desk with his coffee.', '데릭이 커피를 들고 의자를 굴려 당신 자리로 옵니다.',
   'Morning! I left a few comments on your pull request. Did you get a chance to look?', 'Say you saw them but have not gone through all of them yet.', '봤지만 아직 전부 살펴보지는 못했다고 하세요.',
   '[{"all":["saw"]},{"all":["yet"]},{"all":["went through"]},{"all":["looked"]}]',
   'I saw them, but I haven''t gone through all of them yet.',
   '["I took the bus, but it was pretty crowded.","I ordered a latte, but they were out of oat milk.","I signed the forms, but HR has not called back."]',
   '["Say \\"I saw them, but … yet.\\"","Key words: saw, not yet"]', '["\\"I saw them, but … yet.\\"으로 말하세요.","핵심 단어: saw, not yet"]',
   'derek', 'No rush. Most of them are just nits.', '급할 거 없어요. 대부분 사소한 거예요.');

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d2_code_review', 2, 'derek',
   'He points at one comment on your screen.', '그가 화면의 코멘트 하나를 가리킵니다.',
   'The main one is about error handling. Right now, if the payment call fails, we just swallow the error.', 'Ask what he suggests you do instead.', '대신 어떻게 하면 좋을지 제안을 물어보세요.',
   '[{"all":["suggest"]},{"all":["recommend"]},{"all":["what","instead"]},{"all":["how","handle"]}]',
   'Got it. What do you suggest I do instead?',
   '["Got it. What do you usually eat for lunch?","Got it. Where do you usually park?","Got it. When does the next bus come?"]',
                                                                                                                                                                                                                                            '["Ask for his suggestion.","Key words: suggest, instead"]', '["그의 제안을 물어보세요.","핵심 단어: suggest, instead"]',
   'derek', 'Log it, and show the user a friendly message. Maybe add one retry.', '로그를 남기고 사용자에게 친절한 메시지를 보여 줘요. 재시도도 한 번 넣고요.'),
  ('d2_code_review', 3, 'derek',
   'Derek scrolls down to a smaller comment.', '데릭이 작은 코멘트로 스크롤을 내립니다.',
   'Also, a nit: some of your variable names are a little vague, like ''data2''.', 'Say that is fair and you will rename them.', '맞는 말이라며 이름을 바꾸겠다고 하세요.',
   '[{"all":["rename"]},{"all":["fair"]},{"all":["fix"]},{"all":["change"],"any":["names","name","them"]}]',
   'That''s fair. I''ll rename them and push an update.',
   '["That''s far. I''ll take a cab next time.","That''s fine. I''ll have the soup, then.","That''s okay. I''ll call IT about my badge."]',
   '["Agree with \\"That''s fair\\" and say what you will do.","Key words: fair, rename"]', '["\\"That''s fair\\"로 인정하고 할 일을 말하세요.","핵심 단어: fair, rename"]',
   'derek', 'Cool. I''ll approve it once the tests pass.', '좋아요. 테스트 통과하면 승인할게요.'),
  ('d2_code_review', 4, 'derek',
   'He finishes his coffee.', '그가 커피를 마저 마십니다.',
   'One more thing: can you add a unit test for the failure case?', 'Agree, and say you will have it done by the end of the day.', '그러겠다고 하고, 오늘 퇴근 전까지 끝내겠다고 하세요.',
   '[{"all":["end of day"]},{"all":["end of the day"]},{"all":["eod"]},{"all":["today"]},{"all":["this afternoon"]}]',
   'Sure thing. I''ll have it done by end of day.',
   '["Sure thing. I''ll have the club sandwich.","Sure thing. I''ll be at the park on Saturday.","Sure thing. I''ll take the Number 12."]',
   '["Promise a time with \\"by …\\".","Key words: by end of day"]', '["\\"by …\\"로 언제까지 할지 약속하세요.","핵심 단어: by end of day"]',
   'derek', 'Awesome. Thanks for being open to feedback. Not everyone is.', '좋아요. 피드백을 잘 받아 줘서 고마워요. 다 그렇진 않거든요.'),
  ('d2_reschedule', 1, 'priya',
   'Priya catches you after standup with her laptop open.', '스탠드업이 끝나고 프리야가 노트북을 연 채 당신을 붙잡습니다.',
   'Hey, do you have a sec? I want to go over the checkout designs with you. Does one o''clock work?', 'Say sorry, you have an appointment with IT at one.', '미안하지만 한 시에 IT 예약이 있다고 하세요.',
   '[{"any":["appointment","conflict","booked"]},{"all":["something","one"]}]',
   'Sorry, I have an appointment with IT at one.',
   '["Sorry, I have no idea where the lobby is.","Sorry, I don''t eat lunch before noon.","Sorry, I left my umbrella on the bus."]',
   '["Explain what you already have at one.","Key words: appointment, at one"]', '["한 시에 이미 무엇이 있는지 설명하세요.","핵심 단어: appointment, at one"]',
   'priya', 'Oh, no worries.', '아, 괜찮아요.'),
  ('d2_reschedule', 2, 'priya',
   'She opens her calendar.', '그녀가 캘린더를 엽니다.',
   'Could we do it later this afternoon, then?', 'Ask if you could move it to two.', '두 시로 옮길 수 있는지 물어보세요.',
   '[{"any":["two","2","2pm","2 00"]},{"all":["after","appointment"]}]',
   'Could we move it to two o''clock instead?',
   '["Could we move the desk by the window?","Could we order pizza for lunch?","Could we take the stairs instead?"]',
   '["Use \\"Could we move it to …?\\"","Key words: move it to two"]', '["\\"Could we move it to …?\\"를 쓰세요.","핵심 단어: move it to two"]',
   'priya', 'Two works for me. I''ll send you a calendar invite.', '두 시 좋아요. 캘린더 초대 보낼게요.');

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d2_reschedule', 3, 'priya',
   'Priya types the invite.', '프리야가 초대를 입력합니다.',
   'How long do you think we need? Usually thirty minutes, but I can book an hour.', 'Say thirty minutes should be enough.', '30분이면 충분할 것 같다고 하세요.',
   '[{"any":["thirty","30","half an hour","half hour"]}]',
   'Thirty minutes should be plenty.',
   '["About six dollars, I think.","Ten stops from here, I think.","Every Friday, I think."]',
   '["Give a length of time.","Key words: thirty minutes"]', '["시간의 길이를 말하세요.","핵심 단어: thirty minutes"]',
   'priya', 'Great. I''ll book the small room by the kitchen.', '좋아요. 탕비실 옆 작은 방을 예약할게요.'),
  ('d2_reschedule', 4, 'priya',
                                                                                                      'Your laptop dings. The invite is already there.', '노트북에서 알림이 울립니다. 초대가 벌써 와 있습니다.',
   'And if something comes up, just decline it and suggest a new time.', 'Say okay, and that you will keep her posted.', '알겠다고 하고, 상황을 계속 알려 주겠다고 하세요.',
   '[{"all":["posted"]},{"all":["let you know"]},{"any":["sounds good","will do","okay","ok","got it"]}]',
   'Will do. I''ll keep you posted.',
   '["No thanks, I''m just browsing.","It''s on the third floor.","Paper, please."]',
   '["Promise to update her.","Key words: keep you posted"]', '["소식을 알려 주겠다고 약속하세요.","핵심 단어: keep you posted"]',
   'priya', 'Perfect. See you at two!', '좋아요. 두 시에 봐요!'),
  ('d2_it_laptop', 1, 'sam',
   'The IT help desk is a small room full of cables. Sam has three monitors and a cold brew.', 'IT 헬프데스크는 케이블이 가득한 작은 방입니다. 샘 앞에는 모니터 세 대와 콜드브루가 있습니다.',
   'Hey, what''s up? You filed the ticket about your laptop, right?', 'Say yes, and explain it keeps freezing when you run the tests.', '그렇다고 하고, 테스트를 돌리면 자꾸 멈춘다고 설명하세요.',
   '[{"any":["freezing","freezes","froze","frozen","crashing","crashes","hangs","slow"]}]',
   'Yeah, that''s me. My laptop keeps freezing when I run the tests.',
   '["Yeah, that''s me. My neighbor keeps parking in my spot.","Yeah, that''s me. My latte keeps getting cold.","Yeah, that''s me. My badge photo looks terrible."]',
   '["Use \\"keeps …ing\\" for a problem that repeats.","Key words: keeps freezing"]', '["반복되는 문제에는 \\"keeps …ing\\"를 쓰세요.","핵심 단어: keeps freezing"]',
   'sam', 'Ugh, yeah. The older models do that.', '아, 네. 구형 모델이 그래요.'),
  ('d2_it_laptop', 2, 'sam',
   'Sam leans back in his chair.', '샘이 의자에 등을 기댑니다.',
   'Have you tried restarting it?', 'Say yes, you have restarted it twice already.', '네, 벌써 두 번 재시작했다고 하세요.',
   '[{"any":["restarted","rebooted","restart","reboot"]},{"all":["turned it off"]}]',
   'Yes, I''ve restarted it twice already.',
   '["Yes, I''ve been to the diner twice.","Yes, I''ve already met Maya.","Yes, I''ve got my badge right here."]',
   '["Use the present perfect: I''ve …ed.","Key words: restarted, twice"]', '["현재완료 I''ve …ed를 쓰세요.","핵심 단어: restarted, twice"]',
   'sam', 'Okay, then it''s probably the memory. Let me check.', '그럼 아마 메모리 문제예요. 확인해 볼게요.'),
  ('d2_it_laptop', 3, 'sam',
   'He types a few commands on your laptop.', '그가 당신 노트북에 명령어 몇 개를 입력합니다.',
   'Yeah, you''ve only got eight gigs of RAM. I can swap it for a new one, but it''ll take about an hour to set up.', 'Ask if you can use a loaner in the meantime.', '그동안 대여용 노트북을 쓸 수 있는지 물어보세요.',
   '[{"all":["meantime"]},{"all":["loaner"]},{"all":["while"],"any":["wait","work","waiting"]},{"all":["borrow"]}]',
   'That works. Can I use a loaner in the meantime?',
   '["That works. Can I get a refill on my coffee?","That works. Can I pay in cash?","That works. Can I sit by the window?"]',
   '["A \\"loaner\\" is a device you borrow for a while.","Key words: loaner, in the meantime"]', '["loaner는 잠시 빌려 쓰는 기기입니다.","핵심 단어: loaner, in the meantime"]',
   'sam', 'Sure, grab this one. Just log in with your company account.', '그럼요, 이거 가져가요. 회사 계정으로 로그인하면 돼요.');

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d2_it_laptop', 4, 'sam',
   'Sam hands you a scratched but working laptop.', '샘이 긁힌 자국은 있지만 잘 돌아가는 노트북을 건넵니다.',
   'Your new machine should be ready by four. I''ll ping you.', 'Thank him, and ask if you should pick it up here.', '고맙다고 하고, 여기서 찾아가면 되는지 물어보세요.',
   '[{"all":["pick"],"any":["up"]},{"all":["come back"]},{"all":["where"]}]',
   'Thanks, Sam. Should I pick it up here?',
   '["Thanks, Sam. Should I order the pancakes?","Thanks, Sam. Should I take the Number 12 bus?","Thanks, Sam. Should I bring a photo ID?"]',
   '["Use \\"pick it up\\".","Key words: pick up"]', '["pick it up(찾아가다)을 쓰세요.","핵심 단어: pick up"]',
                                                                                                                           'sam', 'Yep, right here. Or I can drop it off at your desk.', '네, 여기요. 아니면 자리로 갖다줄 수도 있어요.'),
  ('d3_one_on_one', 1, 'maya',
   'Maya has two cups of tea on her desk, one for you.', '마야의 책상에 차 두 잔이 있습니다. 하나는 당신 것입니다.',
   'So, first week. How are you settling in?', 'Say it is going well and everyone has been really helpful.', '잘 되고 있고 다들 많이 도와준다고 하세요.',
   '[{"all":["helpful"]},{"all":["going well"]},{"any":["settling","great","good","well"]}]',
   'It''s going well. Everyone''s been really helpful.',
   '["It''s going to rain this afternoon.","It''s on the third floor.","I''d like the soup, please."]',
   '["Say how it is going, and say something about the people.","Key words: going well, helpful"]', '["어떻게 되고 있는지, 사람들은 어떤지 말하세요.","핵심 단어: going well, helpful"]',
   'maya', 'Love to hear that. Derek says you''re picking things up fast.', '반가운 얘기네요. 데릭이 당신이 빨리 배운대요.'),
  ('d3_one_on_one', 2, 'maya',
   'She opens a short list on her laptop.', '그녀가 노트북에서 짧은 목록을 엽니다.',
   'Let''s talk priorities. For the next two weeks, I''d like you to focus on the checkout bug backlog. Does that make sense?', 'Say it makes sense, and ask which bugs you should start with.', '이해했다고 하고, 어떤 버그부터 시작해야 하는지 물어보세요.',
   '[{"all":["which"],"any":["first","start","bug","bugs"]},{"all":["start with"]},{"all":["priority"]},{"all":["most important"]}]',
   'Makes sense. Which bugs should I start with?',
   '["Makes sense. Which bus should I take home?","Makes sense. Which diner has good pie?","Makes sense. Which floor is HR on?"]',
   '["Ask \\"Which … should I start with?\\"","Key words: which, start with"]', '["\\"Which … should I start with?\\"로 물어보세요.","핵심 단어: which, start with"]',
   'maya', 'Start with anything tagged P1. Priya can walk you through them.', 'P1 태그가 붙은 것부터요. 프리야가 자세히 설명해 줄 거예요.'),
  ('d3_one_on_one', 3, 'maya',
   'Maya closes the list and turns to you.', '마야가 목록을 닫고 당신을 봅니다.',
   'Is there anything I can do to support you better?', 'Say it would help to get more context about the product.', '제품에 대한 배경 설명을 더 들으면 도움이 되겠다고 하세요.',
   '[{"all":["context"]},{"all":["background"]},{"all":["more","about","product"]}]',
   'It would help to get more context about the product and our customers.',
   '["It would help to get more sleep, honestly.","It would help to have a closer bus stop.","It would help to have free parking."]',
   '["Use \\"It would help to …\\".","Key words: context, product"]', '["\\"It would help to …\\"를 쓰세요.","핵심 단어: context, product"]',
   'maya', 'Totally fair. I''ll set you up with a product demo next week.', '충분히 그래요. 다음 주에 제품 데모를 잡아 줄게요.'),
  ('d3_one_on_one', 4, 'maya',
   'She writes a note.', '그녀가 메모를 합니다.',
   'And how do you like to get feedback? In the moment, or saved up for our one-on-ones?', 'Say you would prefer to hear it right away.', '바로바로 듣는 게 좋다고 하세요.',
   '[{"any":["right away","in the moment","immediately","as soon as","real time","right then"]}]',
   'I''d prefer to hear it right away, in the moment.',
   '["I''d prefer a window seat, if possible.","I''d prefer oat milk, if you have it.","I''d prefer to pay by card."]',
   '["Use \\"I''d prefer …\\".","Key words: right away"]', '["\\"I''d prefer …\\"를 쓰세요.","핵심 단어: right away"]',
   'maya', 'Noted.', '알겠어요.'),
  ('d3_one_on_one', 5, 'maya',
   'The 1:1 is almost over.', '1:1이 거의 끝나 갑니다.',
   'Let''s keep this weekly. Same time next Wednesday?', 'Agree to the time.', '그 시간에 동의하세요.',
   '[{"any":["works","sounds good","perfect","sure","great","see you"]}]',
   'Sounds good. Same time works for me.',
   '["No, I''m allergic to nuts.","Could I get it to go?","It''s in aisle five."]',
   '["Say the time works for you.","Key words: works for me"]', '["그 시간이 괜찮다고 하세요.","핵심 단어: works for me"]',
   'maya', 'Great. Keep up the good work!', '좋아요. 계속 잘해 줘요!');

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d3_lunch', 1, 'derek',
   'It is almost noon. Derek stands up and grabs his jacket.', '거의 정오입니다. 데릭이 일어나 재킷을 집어 듭니다.',
   'Hey, a few of us are grabbing tacos from the food truck. Wanna come?', 'Accept the invitation.', '초대를 수락하세요.',
   '[{"any":["love to","sure","yes","yeah","count me in","sounds great","absolutely","why not"]}]',
   'Sure, I''d love to. Let me grab my wallet.',
   '["No thanks, I''m just looking.","Sorry, the meeting got moved.","Here''s my photo ID."]',
   '["Say yes warmly.","Key words: sure, I''d love to"]', '["반갑게 좋다고 하세요.","핵심 단어: sure, I''d love to"]',
                                                                                                                                                                                                 'derek', 'Nice! The line gets long after twelve, so let''s go.', '좋아요! 열두 시 넘으면 줄이 길어지니까 가요.'),
  ('d3_lunch', 2, 'derek',
   'You wait in line at the food truck.', '푸드트럭 앞에서 줄을 서 있습니다.',
   'So, any big plans for the weekend?', 'Say not really, but you are thinking of checking out the park and exploring the city.', '별일 없지만 공원에 가 보고 시내를 둘러볼까 한다고 하세요.',
   '[{"any":["park","explore","exploring","check out","checking out","walk","relax","relaxing","nothing much","rest"]}]',
   'Not really. I''m thinking of checking out the park and exploring the city.',
   '["Not really. I''m thinking of filing an IT ticket.","Not really. It''s due on Friday.","Not really. I''ll have the chicken, please."]',
   '["Use \\"I''m thinking of …ing\\".","Key words: check out, park"]', '["\\"I''m thinking of …ing\\"를 쓰세요.","핵심 단어: check out, park"]',
   'derek', 'Oh, you should hit the farmers market at Seaside Park on Saturday. It''s great.', '아, 토요일에 시사이드 공원 파머스 마켓에 꼭 가 봐요. 좋아요.'),
  ('d3_lunch', 3, 'derek',
   'You sit on a bench with your tacos.', '타코를 들고 벤치에 앉습니다.',
   'Where did you live before you moved here?', 'Say where you are from and when you moved.', '어디 출신이고 언제 이사 왔는지 말하세요.',
   '[{"any":["from","lived","grew up","moved","korea","seoul"]}]',
   'I''m originally from Seoul. I moved here about a month ago.',
   '["I''ll take two tacos, please.","It''s about twenty minutes by bus.","I usually get up at seven."]',
   '["Use \\"I''m originally from …\\".","Key words: originally from, moved"]', '["\\"I''m originally from …\\"를 쓰세요.","핵심 단어: originally from, moved"]',
   'derek', 'No way! I''ve always wanted to go.', '정말요? 늘 가 보고 싶었어요.'),
  ('d3_lunch', 4, 'derek',
   'Derek wipes salsa off his hands.', '데릭이 손에 묻은 살사를 닦습니다.',
   'So how are you liking Fairview so far?', 'Say you like it a lot, but you are still getting used to tipping.', '아주 좋지만 팁 문화에는 아직 적응 중이라고 하세요.',
   '[{"any":["tipping","tip","tips","getting used"]}]',
   'I like it a lot, but I''m still getting used to tipping.',
   '["I like it a lot, but the repo is still broken.","I like it a lot, but I left my badge at home.","I like it a lot, but the meeting is at two."]',
   '["Use \\"I''m still getting used to …\\".","Key words: getting used to, tipping"]', '["\\"I''m still getting used to …\\"를 쓰세요.","핵심 단어: getting used to, tipping"]',
   'derek', 'Ha! Everyone struggles with that. Rule of thumb: fifteen to twenty percent at sit-down places.', '하! 다들 그걸 어려워해요. 대충 기준은 앉아서 먹는 곳이면 15~20퍼센트예요.'),
  ('d3_planning', 1, 'priya',
   'The whole team is in the meeting room. A board full of tickets is on the screen.', '팀 전원이 회의실에 있습니다. 화면에 티켓이 가득한 보드가 떠 있습니다.',
   'Welcome to your first sprint planning! We''ll go through the tickets and estimate each one in story points.', 'Ask what one story point means for this team.', '이 팀에서 스토리 포인트 1이 무슨 뜻인지 물어보세요.',
   '[{"all":["story point"]},{"all":["point"],"any":["what","mean"]},{"all":["points"],"any":["what","mean"]}]',
   'Quick question: what does one story point mean for this team?',
   '["Quick question: what does the soup come with?","Quick question: what time does the bus leave?","Quick question: where is the IT desk?"]',
   '["Ask \\"What does … mean?\\"","Key words: story point, mean"]', '["\\"What does … mean?\\"으로 물어보세요.","핵심 단어: story point, mean"]',
   'priya', 'Good question. It''s about effort and complexity, not hours. A one is tiny, an eight is big.', '좋은 질문이에요. 시간이 아니라 노력과 복잡도예요. 1은 아주 작고 8은 커요.');

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d3_planning', 2, 'priya',
   'Priya opens the first ticket.', '프리야가 첫 번째 티켓을 엽니다.',
   'First ticket: add a ''save card for later'' checkbox to checkout. What would you estimate?', 'Give an estimate (for example, three points) and say why.', '추정치(예: 3포인트)와 이유를 말하세요.',
   '[{"any":["one","two","three","five","eight","1","2","3","5","8"]}]',
   'I''d say a three. The UI is simple, but we need to test it carefully.',
   '["I''d say it''s a nice day for a walk.","I''d say the latte was better.","I''d say paper, not plastic."]',
                                                                                                                                                                                                                                                                                   '["Start with \\"I''d say a …\\" and a number.","Key words: I''d say, three"]', '["\\"I''d say a …\\"와 숫자로 시작하세요.","핵심 단어: I''d say, three"]',
   'priya', 'Derek said three too. Three it is.', '데릭도 3이래요. 3으로 하죠.'),
  ('d3_planning', 3, 'priya',
   'The next ticket has only one line: "Refunds sometimes fail."', '다음 티켓에는 딱 한 줄뿐입니다: "환불이 가끔 실패함."',
   'Next one''s the refund bug. It''s pretty vague. Anybody want to take it?', 'Say you can take it, but you need more details first.', '맡을 수 있지만 먼저 세부 정보가 더 필요하다고 하세요.',
   '[{"all":["details"]},{"all":["more info"]},{"all":["information"]},{"all":["clarify"]},{"all":["take it"]}]',
   'I can take it, but I''ll need more details first.',
   '["I can take the bus, but I''ll be a little late.","I can take a message, but Maya is out.","I can take the stairs, but my knee hurts."]',
   '["Volunteer with \\"I can take it, but …\\".","Key words: take it, more details"]', '["\\"I can take it, but …\\"로 자원하세요.","핵심 단어: take it, more details"]',
   'priya', 'Love it. I''ll add the customer''s steps to the ticket.', '좋아요. 고객이 겪은 단계를 티켓에 추가할게요.'),
  ('d3_planning', 4, 'priya',
   'The sprint board is full now.', '이제 스프린트 보드가 꽉 찼습니다.',
   'Okay, I think we''re at capacity. Does anyone feel like this sprint is too much?', 'Say the workload looks doable to you.', '업무량이 해낼 만해 보인다고 하세요.',
   '[{"any":["doable","manageable","reasonable","fine","okay","good"]}]',
   'It looks doable to me.',
   '["It looks like rain to me.","It looks like the wrong bus to me.","It looks delicious to me."]',
   '["Use \\"It looks … to me.\\"","Key words: doable"]', '["\\"It looks … to me.\\"를 쓰세요.","핵심 단어: doable"]',
   'priya', 'Great. Let''s lock it in. Thanks, everyone!', '좋아요. 이걸로 확정해요. 다들 고마워요!'),
  ('d4_deadline', 1, 'priya',
   'Priya stops by the meeting room door with her coffee.', '프리야가 커피를 들고 회의실 문 앞에 멈춰 섭니다.',
   'How''s the refund bug coming along? Are we still on track for Friday?', 'Say honestly that it is taking longer than you expected.', '생각보다 오래 걸리고 있다고 솔직하게 말하세요.',
   '[{"all":["longer"]},{"any":["behind","delayed","tricky","complicated","harder"]}]',
   'Honestly, it''s taking longer than I expected.',
   '["Honestly, the bus was faster than I expected.","Honestly, the pie was better than I expected.","Honestly, it''s colder than I expected."]',
   '["Use \\"It''s taking longer than …\\".","Key words: taking longer"]', '["\\"It''s taking longer than …\\"을 쓰세요.","핵심 단어: taking longer"]',
   'priya', 'Okay. Thanks for flagging it early.', '알겠어요. 일찍 알려 줘서 고마워요.'),
  ('d4_deadline', 2, 'priya',
   'She sits down across from you.', '그녀가 맞은편에 앉습니다.',
   'What''s slowing you down?', 'Explain the bug is in old code with no tests.', '버그가 테스트가 없는 오래된 코드에 있다고 설명하세요.',
   '[{"any":["tests","test","legacy","old code","documentation"]}]',
   'The bug is in some old code, and there are no tests for it.',
   '["The bus is on Maple Street, and it runs every ten minutes.","The diner is closed, and the market is too far.","The coffee is great, and the barista is nice."]',
   '["Say where the bug is and what is missing.","Key words: old code, no tests"]', '["버그가 어디 있고 무엇이 없는지 말하세요.","핵심 단어: old code, no tests"]',
   'priya', 'Ah, the legacy stuff. That makes sense.', '아, 레거시 코드군요. 그럴 만하네요.');

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d4_deadline', 3, 'priya',
   'Priya taps her pen on the table.', '프리야가 펜으로 테이블을 톡톡 칩니다.',
   'So what do you need? More time?', 'Ask if you could push the deadline to next Tuesday.', '마감을 다음 주 화요일로 미룰 수 있는지 물어보세요.',
   '[{"all":["push"],"any":["deadline","tuesday","back"]},{"all":["tuesday"]},{"all":["extend"]},{"all":["more time"]},{"all":["extension"]}]',
   'Could we push the deadline to next Tuesday?',
   '["Could we push the meeting to lunch?","Could we get a table by the window?","Could we split the check?"]',
                                                                                                                                                                                                                                                                         '["Use \\"Could we push … to …?\\"","Key words: push the deadline, Tuesday"]', '["\\"Could we push … to …?\\"를 쓰세요.","핵심 단어: push the deadline, Tuesday"]',
   'priya', 'Hmm. Tuesday''s tough. The client demo is on Monday.', '음. 화요일은 힘들어요. 고객 데모가 월요일이거든요.'),
  ('d4_deadline', 4, 'priya',
   'She thinks for a moment.', '그녀가 잠시 생각합니다.',
   'Is there any way to cut the scope and ship part of it on Friday?', 'Suggest shipping the fix for card payments first and the rest next week.', '카드 결제 수정부터 먼저 내보내고 나머지는 다음 주에 하자고 제안하세요.',
   '[{"all":["first"]},{"all":["next week"]},{"all":["rest","later"]},{"all":["phase"]}]',
   'We could ship the fix for card payments first and do the rest next week.',
   '["We could order pizza and eat at our desks.","We could take the bus and walk from there.","We could meet at the park on Sunday."]',
   '["Suggest with \\"We could … first and … next week.\\"","Key words: first, next week"]', '["\\"We could … first and … next week.\\"로 제안하세요.","핵심 단어: first, next week"]',
   'priya', 'That''s a great compromise. Let''s do that. I''ll update the ticket.', '좋은 절충안이에요. 그렇게 해요. 티켓을 고칠게요.'),
  ('d4_benefits', 1, 'linda',
   'Linda has a folder with your name on it.', '린다 앞에 당신 이름이 적힌 폴더가 있습니다.',
   'Hi! Thanks for coming by. We just need to finish your new-hire paperwork. Did you fill out your W-4 yet?', 'Say not yet, and ask what the W-4 is for.', '아직이라고 하고, W-4가 무엇을 위한 것인지 물어보세요.',
   '[{"all":["what"],"any":["for","does","is"]}]',
   'Not yet. What''s the W-4 for, exactly?',
   '["Not yet. Where''s the break room?","Not yet. Can I bring my lunch?","Not yet. How late is the diner open?"]',
   '["Ask \\"What''s … for?\\"","Key words: what''s it for"]', '["\\"What''s … for?\\"로 물어보세요.","핵심 단어: what''s it for"]',
   'linda', 'It tells payroll how much federal income tax to withhold from each paycheck.', '급여팀에 매 급여에서 연방 소득세를 얼마나 떼어 둘지 알려 주는 양식이에요.'),
  ('d4_benefits', 2, 'linda',
   'She puts two brochures in front of you.', '그녀가 안내 책자 두 개를 당신 앞에 놓습니다.',
   'Next, health insurance. The PPO costs more per paycheck. The HMO is cheaper, but you need a referral to see a specialist.', 'Ask which plan has the lower deductible.', '어느 플랜의 본인 부담 공제액이 더 낮은지 물어보세요.',
   '[{"all":["deductible"]},{"all":["which","plan"]},{"all":["difference"]}]',
   'Which plan has the lower deductible?',
   '["Which bus has the lower fare?","Which diner has the better pie?","Which floor has the break room?"]',
   '["A \\"deductible\\" is what you pay before insurance starts paying.","Key words: which plan, deductible"]', '["deductible은 보험이 지급하기 전에 내가 먼저 내는 금액입니다.","핵심 단어: which plan, deductible"]',
   'linda', 'The PPO. Its deductible is five hundred dollars. The HMO''s is fifteen hundred.', 'PPO요. 공제액이 500달러예요. HMO는 1,500달러고요.'),
  ('d4_benefits', 3, 'linda',
   'You look at the monthly costs.', '월 비용을 살펴봅니다.',
   'A lot of people your age go with the HMO. But if you see doctors a lot, the PPO is worth it. Which one would you like?', 'Pick one plan and give a reason.', '플랜 하나를 고르고 이유를 말하세요.',
   '[{"any":["ppo","hmo"]}]',
   'I''ll go with the PPO. I''d like to choose my own doctors.',
   '["I''ll go with the club sandwich.","I''ll go with oat milk.","I''ll go with the Number 12 bus."]',
   '["Choose with \\"I''ll go with …\\".","Key words: I''ll go with, PPO or HMO"]', '["\\"I''ll go with …\\"로 고르세요.","핵심 단어: I''ll go with, PPO 또는 HMO"]',
   'linda', 'Good choice. Open enrollment closes in thirty days, so you can still change your mind.', '좋은 선택이에요. 가입 기간이 30일 뒤에 끝나니까 그 전에는 바꿀 수 있어요.');

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d4_benefits', 4, 'linda',
   'Linda turns to the last page.', '린다가 마지막 장을 넘깁니다.',
   'Last thing: the 401(k). The company matches up to four percent. Want to sign up?', 'Say yes, and that you will put in four percent to get the full match.', '그렇다고 하고, 4퍼센트를 넣어 회사 매칭을 다 받겠다고 하세요.',
   '[{"all":["match"]},{"any":["four percent","4 percent","4%","contribute","enroll"]}]',
   'Definitely. I''ll contribute four percent to get the full match.',
   '["Definitely. I''ll take the bus home tonight.","Definitely. I''ll have the apple pie.","Definitely. I''ll move the meeting to two."]',
                                                                                                                                                                                                            '["Say how much you will contribute.","Key words: four percent, full match"]', '["얼마를 넣을지 말하세요.","핵심 단어: four percent, full match"]',
   'linda', 'Smart move. That''s free money. And you''re all set!', '현명해요. 공짜 돈이니까요. 이제 다 됐어요!'),
  ('d4_pto', 1, 'maya',
   'You knock on the frame of Maya''s open door.', '마야의 열린 문틀을 똑똑 두드립니다.',
   'Hey, come on in. What''s up?', 'Say you have a quick question about time off.', '휴가에 대해 간단한 질문이 있다고 하세요.',
   '[{"any":["time off","pto","vacation","day off","days off","leave"]}]',
   'I had a quick question about time off.',
   '["I had a quick question about the bus schedule.","I had a quick question about the diner menu.","I had a quick question about story points."]',
   '["Use \\"I had a quick question about …\\".","Key words: question, time off"]', '["\\"I had a quick question about …\\"을 쓰세요.","핵심 단어: question, time off"]',
   'maya', 'Sure, shoot.', '그럼요, 말해 봐요.'),
  ('d4_pto', 2, 'maya',
   'Maya turns away from her screen.', '마야가 화면에서 몸을 돌립니다.',
   'What do you want to know?', 'Ask how many PTO days you get a year.', '1년에 유급휴가가 며칠인지 물어보세요.',
   '[{"all":["how many"],"any":["days","pto","vacation"]},{"all":["how much"],"any":["pto","time off","vacation"]}]',
   'How many PTO days do we get a year?',
   '["How many stops is it to downtown?","How many tacos did you order?","How many people are on the team?"]',
   '["Start with \\"How many …\\".","Key words: how many, PTO days"]', '["\\"How many …\\"로 시작하세요.","핵심 단어: how many, PTO days"]',
   'maya', 'Fifteen days of PTO, plus ten company holidays. It builds up a little every paycheck.', '유급휴가 15일에 회사 휴일이 10일이에요. 급여마다 조금씩 쌓여요.'),
  ('d4_pto', 3, 'maya',
   'She smiles.', '그녀가 웃습니다.',
   'Why, got a trip coming up?', 'Say your friend is getting married next month, and ask if you could take two days off.', '다음 달 친구 결혼식이 있다고 하고, 이틀 쉴 수 있는지 물어보세요.',
   '[{"all":["wedding"]},{"all":["married"]},{"all":["two days"]},{"all":["take","off"]}]',
   'Yeah, my friend is getting married next month. Could I take two days off?',
   '["Yeah, my friend is getting a new laptop next month.","Yeah, my bus is running late today.","Yeah, my order is for here."]',
   '["Use \\"Could I take … off?\\"","Key words: getting married, take two days off"]', '["\\"Could I take … off?\\"를 쓰세요.","핵심 단어: getting married, take two days off"]',
   'maya', 'Of course! Just put it in the HR portal and I''ll approve it.', '물론이죠! HR 포털에 올리면 승인할게요.'),
  ('d4_pto', 4, 'maya',
   'Maya adds one more thing.', '마야가 한 가지를 덧붙입니다.',
   'And if you''re ever sick, don''t come in. Just message me before standup.', 'Ask if sick days are separate from PTO.', '병가가 유급휴가와 따로인지 물어보세요.',
   '[{"all":["separate"]},{"all":["sick days"]},{"all":["sick"],"any":["count","different","same"]}]',
   'Good to know. Are sick days separate from PTO?',
   '["Good to know. Are tacos cheaper on Tuesdays?","Good to know. Are the elevators on the left?","Good to know. Is standup at ten again?"]',
   '["Ask \\"Are … separate from …?\\"","Key words: sick days, separate"]', '["\\"Are … separate from …?\\"로 물어보세요.","핵심 단어: sick days, separate"]',
   'maya', 'Yep, you get five sick days. And please actually use them if you need to!', '네, 병가는 5일이에요. 필요하면 진짜로 써요!'),
  ('d5_demo', 1, 'priya',
   'The team and a few people from sales are in the meeting room.', '회의실에 팀원들과 영업팀 몇 명이 있습니다.',
   'Okay, demo time! You''re up first. Want to show us the card payment fix?', 'Say sure, and that you will share your screen.', '좋다고 하고, 화면을 공유하겠다고 하세요.',
   '[{"all":["share"]},{"all":["screen"]}]',
   'Sure. Let me share my screen.',
   '["Sure. Let me grab my wallet.","Sure. Let me call IT about my badge.","Sure. Let me check the bus schedule."]',
   '["Use \\"Let me …\\".","Key words: share my screen"]', '["\\"Let me …\\"를 쓰세요.","핵심 단어: share my screen"]',
   'priya', 'We can see it. Go ahead.', '보여요. 시작해요.');

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d5_demo', 2, 'priya',
   'The checkout page is on the big screen.', '큰 화면에 결제 페이지가 떠 있습니다.',
   'Walk us through what changed.', 'Explain that a failed payment now shows a clear error message and retries once.', '결제가 실패하면 이제 분명한 오류 메시지가 나오고 한 번 재시도한다고 설명하세요.',
   '[{"any":["error message","retry","retries","message","error"]}]',
   'Now, if a payment fails, the user sees a clear error message, and we retry once automatically.',
   '["Now, if the bus is late, I usually walk to work.","Now, if the diner is busy, we go to the food truck.","Now, if it rains, the park is closed."]',
                                                                                                                                                                                  '["Say what happens now when a payment fails.","Key words: error message, retry"]', '["이제 결제가 실패하면 어떻게 되는지 말하세요.","핵심 단어: error message, retry"]',
   'priya', 'Nice! That''ll cut down on support tickets for sure.', '좋아요! 고객 문의 티켓이 확실히 줄겠네요.'),
  ('d5_demo', 3, 'priya',
   'After the demo, Priya draws two columns on the whiteboard.', '데모가 끝나고 프리야가 화이트보드에 두 칸을 그립니다.',
   'Let''s switch to the retro. What went well this sprint?', 'Say the team was really supportive and the code reviews helped.', '팀이 많이 도와줬고 코드 리뷰가 도움이 됐다고 하세요.',
   '[{"any":["supportive","helpful","team","reviews","review","support"]}]',
   'The team was really supportive, and the code reviews were super helpful.',
   '["The pancakes were really good this morning.","The bus was really crowded this week.","The weather was really nice on Tuesday."]',
   '["Name something good about working together.","Key words: supportive, code reviews"]', '["함께 일하면서 좋았던 점을 말하세요.","핵심 단어: supportive, code reviews"]',
   'priya', 'Aw, love that.', '와, 좋네요.'),
  ('d5_demo', 4, 'priya',
   'Priya points at the second column.', '프리야가 두 번째 칸을 가리킵니다.',
   'And what could we do better?', 'Say some tickets could be clearer before planning.', '플래닝 전에 티켓이 더 명확하면 좋겠다고 하세요.',
   '[{"any":["clearer","clear","details","detail","requirements","vague"]}]',
   'Some tickets could be clearer before planning. The refund bug was a little vague.',
   '["The coffee could be a little stronger.","The office could use more plants.","The diner could stay open later."]',
   '["Give polite, useful feedback about the work.","Key words: tickets, clearer"]', '["일에 대해 정중하고 쓸모 있는 피드백을 주세요.","핵심 단어: tickets, clearer"]',
   'priya', 'Totally fair. I''ll add acceptance criteria to every ticket from now on.', '맞는 말이에요. 앞으로 모든 티켓에 인수 조건을 적을게요.'),
  ('d5_paystub', 1, 'linda',
   'Your first paycheck hit your bank account this morning. You bring the pay stub to HR.', '오늘 아침 첫 급여가 계좌에 들어왔습니다. 급여명세서를 들고 인사팀에 갑니다.',
   'Happy payday! What can I do for you?', 'Say you have a question about your pay stub.', '급여명세서에 대해 질문이 있다고 하세요.',
   '[{"any":["pay stub","paystub","paycheck","stub","payslip","pay slip"]}]',
   'Hi, Linda. I have a question about my pay stub.',
   '["Hi, Linda. I have a question about the diner menu.","Hi, Linda. I have a question about story points.","Hi, Linda. I have a question about my commute."]',
   '["The paper that shows your pay is a \\"pay stub\\".","Key words: question, pay stub"]', '["급여 내역서는 pay stub이라고 합니다.","핵심 단어: question, pay stub"]',
   'linda', 'Sure! Let''s pull it up together.', '그럼요! 같이 열어 봐요.'),
  ('d5_paystub', 2, 'linda',
   'Linda points at the top of the stub.', '린다가 명세서 맨 위를 가리킵니다.',
   'This top number, thirty-six fifty-four, is your gross pay. That''s before anything comes out.', 'Point to the next line and ask what federal withholding is.', '다음 줄을 가리키며 federal withholding이 뭔지 물어보세요.',
   '[{"all":["withholding"]},{"all":["federal"]},{"all":["tax"]}]',
   'What''s this line, federal withholding?',
   '["What''s this line, the Number 12 route?","What''s this, a coffee refill?","What''s the soup of the day?"]',
   '["Read the words on the line and ask about them.","Key words: federal withholding"]', '["그 줄의 단어를 읽고 물어보세요.","핵심 단어: federal withholding"]',
   'linda', 'That''s federal income tax, based on your W-4. You settle up when you file your taxes in April.', 'W-4에 따라 떼는 연방 소득세예요. 4월에 세금 신고할 때 정산해요.');

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d5_paystub', 3, 'linda',
   'Below that there are more lines: FICA, state tax, health insurance, 401(k).', '그 아래에 더 많은 줄이 있습니다: FICA, 주세, 건강보험, 401(k).',
   'Then FICA. That''s Social Security and Medicare. Everyone pays that, seven point six five percent.', 'Ask where your 401(k) contribution is.', '401(k) 납입액은 어디 있는지 물어보세요.',
   '[{"all":["401"]},{"all":["retirement"]},{"all":["contribution"]}]',
   'Got it. And where''s my 401(k) contribution?',
   '["Got it. And where''s the nearest bus stop?","Got it. And where''s the break room?","Got it. And where''s my badge?"]',
                                                                                                                                                                                                                         '["Ask \\"Where''s my …?\\"","Key words: 401(k) contribution"]', '["\\"Where''s my …?\\"로 물어보세요.","핵심 단어: 401(k) contribution"]',
   'linda', 'Right here: four percent, a hundred forty-six dollars. It comes out pre-tax.', '여기요. 4퍼센트, 146달러예요. 세전으로 빠져요.'),
  ('d5_paystub', 4, 'linda',
   'At the bottom is the number you saw in your bank account.', '맨 아래에 은행 계좌에서 본 숫자가 있습니다.',
   'After all that, your net pay, your take-home, is twenty-six hundred. It goes straight to your bank by direct deposit.', 'Say it makes sense now and thank her.', '이제 이해가 된다고 하고 고맙다고 하세요.',
   '[{"any":["makes sense","thanks","thank","clear","got it","understand"]}]',
   'That makes a lot more sense now. Thanks, Linda!',
   '["Can I get a refill, please?","I''d like to return this sweater.","The deadline is next Tuesday."]',
   '["Say you understand now, and thank her.","Key words: makes sense, thanks"]', '["이제 이해했다고 하고 고맙다고 하세요.","핵심 단어: makes sense, thanks"]',
   'linda', 'Anytime! And hey, don''t spend it all in one place.', '언제든지요! 그리고 한 번에 다 쓰지 마요.'),
  ('d5_happy_hour', 1, 'derek',
   'It is Friday afternoon. Derek is packing up his laptop.', '금요일 오후입니다. 데릭이 노트북을 챙기고 있습니다.',
   'Hey, a bunch of us are going to happy hour at the Anchor after work. You in?', 'Thank him, but politely say you are too tired this week.', '고맙다고 하고, 이번 주는 너무 피곤하다고 정중히 거절하세요.',
   '[{"any":["wiped","tired","exhausted","beat","next time","rain check"]},{"all":["love to","but"]}]',
   'Thanks for the invite! I''d love to, but I''m pretty wiped out this week.',
   '["Thanks for the invite! I''ll have a cheeseburger, medium.","Thanks for the invite! My badge isn''t working.","Thanks for the invite! Paper is fine."]',
   '["Use \\"I''d love to, but …\\".","Key words: I''d love to, but, tired"]', '["\\"I''d love to, but …\\"를 쓰세요.","핵심 단어: I''d love to, but, tired"]',
   'derek', 'Totally get it. The first week is exhausting.', '완전 이해해요. 첫 주는 진 빠지죠.'),
  ('d5_happy_hour', 2, 'derek',
   'He zips up his bag.', '그가 가방 지퍼를 올립니다.',
   'No pressure at all. We go pretty much every other Friday.', 'Ask for a rain check and say you will come next time.', '다음을 기약하고, 다음번엔 꼭 가겠다고 하세요.',
   '[{"any":["rain check","next time","count me in"]}]',
   'Can I take a rain check? I''ll definitely come next time.',
   '["Can I take the stairs? The elevator is slow.","Can I get the check? I''m in a hurry.","Can I pay by card? I don''t have cash."]',
   '["\\"Take a rain check\\" = accept later instead.","Key words: rain check, next time"]', '["take a rain check는 다음에 받겠다는 뜻입니다.","핵심 단어: rain check, next time"]',
   'derek', 'Rain check it is. I''m holding you to that!', '다음으로 미루죠. 약속 지켜요!'),
  ('d5_happy_hour', 3, 'derek',
   'Derek puts on his jacket.', '데릭이 재킷을 입습니다.',
   'Any plans for tonight, then?', 'Say you are just going to get some groceries and rest.', '장 좀 보고 쉴 거라고 하세요.',
   '[{"any":["groceries","grocery","relax","rest","sleep","home","chill","nothing much"]}]',
   'Just grabbing some groceries and getting some rest.',
   '["Just the check, please.","Just a medium latte, please.","Just a quick question about PTO."]',
   '["Start with \\"Just …ing\\".","Key words: groceries, rest"]', '["\\"Just …ing\\"로 시작하세요.","핵심 단어: groceries, rest"]',
   'derek', 'Sounds perfect. You earned it.', '딱 좋네요. 그럴 자격 있어요.');

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d5_happy_hour', 4, 'derek',
   'He stops at the door and turns around.', '그가 문 앞에서 멈춰 돌아봅니다.',
   'Oh, and great job at the demo today, by the way.', 'Thank him for the compliment and wish him a good weekend.', '칭찬에 고맙다고 하고 좋은 주말 보내라고 하세요.',
   '[{"any":["thanks","thank","appreciate"]}]',
   'Thanks, that means a lot! Have a great weekend.',
   '["Sorry, I don''t have change.","No, I''ll take the next bus.","It''s the second door on the left."]',
   '["Thank him, then say goodbye for the weekend.","Key words: thanks, great weekend"]', '["고맙다고 하고 주말 인사를 하세요.","핵심 단어: thanks, great weekend"]',
                                                                                                                                                                'derek', 'You too! See you Monday.', '당신도요! 월요일에 봐요.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('d1_bus.heading_into_work', 'd1_bus', 'Heading into work?', '출근하는 길이에요?', 'A friendly morning question; "heading" means going.', '아침에 가볍게 묻는 말입니다. heading은 가는 중이라는 뜻입니다.', 'commute'),
  ('d1_bus.no_kidding', 'd1_bus', 'No kidding!', '정말요? / 설마!', 'Shows surprise at good or surprising news.', '좋은 소식이나 놀라운 소식에 놀라움을 나타냅니다.', 'small-talk'),
  ('d1_bus.new_gig', 'd1_bus', 'Where''s the new gig?', '새 일자리는 어디예요?', '"Gig" is a casual word for a job.', 'gig는 일자리를 가리키는 편한 말입니다.', 'small-talk'),
  ('d1_bus.any_minute', 'd1_bus', 'It should be here any minute.', '곧 올 거예요.', '"Any minute" means very soon.', 'any minute는 곧, 금방이라는 뜻입니다.', 'commute'),
                                                                                                                         ('d1_bus.tap_card', 'd1_bus', 'Can I just tap my card?', '카드를 대기만 하면 돼요?', 'Most US buses and shops take contactless cards.', '미국 버스와 가게 대부분은 비접촉 카드를 받습니다.', 'commute'),
  ('d1_bus.have_a_good_one', 'd1_bus', 'Have a good one!', '좋은 하루 보내요!', 'A casual goodbye; answer with "You too!"', '편한 작별 인사입니다. "You too!"로 답합니다.', 'small-talk'),
  ('d1_bus.knock_em_dead', 'd1_bus', 'Knock ''em dead!', '가서 멋지게 해내!', 'Said to cheer someone on before a big day or performance.', '중요한 날이나 발표를 앞둔 사람을 응원할 때 씁니다.', 'small-talk'),
  ('d1_coffee.get_started', 'd1_coffee', 'What can I get started for you?', '뭘 준비해 드릴까요?', 'Baristas say this to take your order.', '바리스타가 주문을 받을 때 하는 말입니다.', 'food'),
  ('d1_coffee.can_i_get', 'd1_coffee', 'Can I get a medium latte, please?', '라테 미디엄 하나 주시겠어요?', '"Can I get …?" is the most common way to order in the US.', '"Can I get …?"은 미국에서 가장 흔한 주문 표현입니다.', 'food'),
  ('d1_coffee.milk_preference', 'd1_coffee', 'Any milk preference?', '우유는 뭘로 할까요?', 'Common choices: whole, skim (fat-free), oat, almond.', '보통 whole(일반), skim(무지방), oat(귀리), almond(아몬드) 중에 고릅니다.', 'food'),
  ('d1_coffee.name_for_order', 'd1_coffee', 'What''s the name for the order?', '주문하신 분 성함이 뭐예요?', 'They write your name on the cup and call it when it is ready.', '컵에 이름을 적어 두었다가 음료가 나오면 불러 줍니다.', 'food'),
  ('d1_coffee.thatll_be', 'd1_coffee', 'That''ll be four seventy-five.', '4달러 75센트입니다.', 'Prices are said as two numbers: four (dollars) seventy-five (cents).', '가격은 달러와 센트를 두 숫자로 나눠 말합니다.', 'shopping'),
  ('d1_coffee.card_or_cash', 'd1_coffee', 'Card or cash?', '카드예요, 현금이에요?', 'Answer "Card, please." or "Cash."', '"Card, please." 또는 "Cash."로 답합니다.', 'shopping'),
  ('d1_coffee.up_to_you', 'd1_coffee', 'Totally up to you.', '전적으로 당신 마음이에요.', 'Means it is your choice. Tips at a coffee counter are optional.', '당신이 정하라는 뜻입니다. 카운터 커피의 팁은 선택입니다.', 'food'),
  ('d1_badge.first_day', 'd1_badge', 'It''s my first day here.', '오늘 여기 첫 출근이에요.', 'A friendly way to explain why you do not know your way around yet.', '아직 이곳을 잘 모른다는 것을 자연스럽게 알리는 표현입니다.', 'office'),
  ('d1_badge.welcome_aboard', 'd1_badge', 'Welcome aboard!', '입사를 환영해요!', 'Said to someone joining a company or team.', '회사나 팀에 합류한 사람에게 하는 말입니다.', 'office'),
  ('d1_badge.photo_id', 'd1_badge', 'I just need to see a photo ID.', '사진 있는 신분증만 보여 주세요.', 'A photo ID is usually a driver''s license or passport.', 'photo ID는 보통 운전면허증이나 여권입니다.', 'office'),
  ('d1_badge.here_you_go', 'd1_badge', 'Here you go.', '여기 있어요.', 'Say this when you hand something to someone.', '무언가를 건네줄 때 하는 말입니다.', 'small-talk'),
  ('d1_badge.what_if_forget', 'd1_badge', 'What should I do if I forget my badge?', '출입증을 깜빡하면 어떻게 하죠?', '"What should I do if …?" asks about a backup plan.', '"What should I do if …?"는 만일의 경우를 묻는 표현입니다.', 'office'),
  ('d1_badge.on_three', 'd1_badge', 'Maya''s expecting you on three.', '마야가 3층에서 기다리고 있어요.', '"On three" means on the third floor.', 'on three는 3층에서라는 뜻입니다.', 'office'),
  ('d1_badge.i_appreciate_it', 'd1_badge', 'I appreciate it.', '정말 고마워요.', 'A slightly warmer way to say thank you.', '고마움을 조금 더 따뜻하게 전하는 말입니다.', 'small-talk'),
  ('d1_badge.anytime', 'd1_badge', 'Anytime.', '언제든지요.', 'A casual reply to "Thank you."', '"Thank you."에 편하게 답하는 말입니다.', 'small-talk');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('d1_onboarding.you_made_it', 'd1_onboarding', 'You made it!', '잘 왔어요! / 무사히 왔네요!', 'A warm greeting when someone arrives, especially for the first time.', '누군가 도착했을 때, 특히 처음 왔을 때 반갑게 하는 인사입니다.', 'office'),
  ('d1_onboarding.how_was_commute', 'd1_onboarding', 'How was the commute?', '출근길은 어땠어요?', '"Commute" is the trip between home and work.', 'commute는 집과 직장 사이를 오가는 길입니다.', 'commute'),
  ('d1_onboarding.nightmare', 'd1_onboarding', 'Parking downtown is a nightmare.', '시내 주차는 악몽이에요.', '"A nightmare" = very difficult or annoying.', 'a nightmare는 몹시 힘들거나 짜증 나는 일을 뜻합니다.', 'small-talk'),
                                                                                                                                                                                                       ('d1_onboarding.get_access', 'd1_onboarding', 'When will I get access to the code repository?', '코드 저장소 권한은 언제 받나요?', 'Ask this when you need permissions for a system.', '어떤 시스템의 권한이 필요할 때 묻는 표현입니다.', 'office'),
  ('d1_onboarding.onboarding_buddy', 'd1_onboarding', 'onboarding buddy', '온보딩 버디(적응 도우미 동료)', 'A coworker who helps a new hire in the first weeks.', '신입의 첫 몇 주를 도와주는 동료입니다.', 'office'),
  ('d1_onboarding.working_on', 'd1_onboarding', 'What''s the team working on right now?', '팀은 지금 무슨 일을 하고 있어요?', 'A good question for your first days on a team.', '팀에 합류한 첫날들에 하기 좋은 질문입니다.', 'office'),
  ('d1_onboarding.any_questions', 'd1_onboarding', 'Let me know if you have any questions.', '궁금한 거 있으면 말해 주세요.', 'Very common at work. Answer "Will do, thanks!"', '직장에서 매우 흔한 말입니다. "Will do, thanks!"로 답합니다.', 'office'),
  ('d1_onboarding.door_always_open', 'd1_onboarding', 'My door''s always open.', '언제든 찾아와도 돼요.', 'A manager''s way to say you can come talk anytime.', '언제든 이야기하러 와도 된다는 매니저의 말입니다.', 'office'),
  ('d1_standup.lets_get_started', 'd1_standup', 'Let''s get started.', '시작합시다.', 'The usual way to open a meeting.', '회의를 시작할 때 흔히 하는 말입니다.', 'meeting'),
  ('d1_standup.excited_to_be_here', 'd1_standup', 'Excited to be here!', '함께하게 돼서 설레요!', 'A friendly end to a self-introduction at work.', '직장에서 자기소개를 밝게 마무리하는 말입니다.', 'meeting'),
  ('d1_standup.on_your_plate', 'd1_standup', 'What''s on your plate today?', '오늘 할 일이 뭐예요?', '"On your plate" = the work you have to do.', 'on your plate는 해야 할 일을 뜻합니다.', 'meeting'),
  ('d1_standup.any_blockers', 'd1_standup', 'Any blockers?', '막힌 거 있어요?', 'A blocker is anything that stops your work. Say "No blockers" if there are none.', 'blocker는 일을 막는 모든 것입니다. 없으면 "No blockers."라고 합니다.', 'meeting'),
  ('d1_standup.dont_have_access', 'd1_standup', 'I don''t have access to the repository yet.', '아직 저장소 권한이 없어요.', 'A common blocker for new hires.', '신입에게 흔한 blocker입니다.', 'office'),
  ('d1_standup.thats_it', 'd1_standup', 'That''s it for today.', '오늘은 여기까지예요.', 'Ends a meeting or a list.', '회의나 목록을 끝낼 때 씁니다.', 'meeting'),
  ('d1_standup.short_and_sweet', 'd1_standup', 'Short and sweet.', '짧고 굵게.', 'Brief and pleasant; people like short meetings.', '짧고 좋다는 뜻입니다. 사람들은 짧은 회의를 좋아합니다.', 'meeting'),
  ('d1_standup.fifteen_max', 'd1_standup', 'fifteen minutes max', '길어야 15분', '"Max" (maximum) after a number means "at most".', '숫자 뒤의 max는 "최대"라는 뜻입니다.', 'meeting'),
  ('d1_desk.new_hire', 'd1_desk', 'You must be the new hire.', '새로 온 분이군요.', '"New hire" = a person who just joined the company.', 'new hire는 막 입사한 사람입니다.', 'office'),
  ('d1_desk.likewise', 'd1_desk', 'Likewise.', '저도요.', 'A short answer to "Nice to meet you."', '"Nice to meet you."에 대한 짧은 대답입니다.', 'small-talk'),
  ('d1_desk.setup_guide', 'd1_desk', 'Is there a setup guide I can follow?', '따라 할 수 있는 설치 가이드가 있나요?', 'Ask for documentation instead of guessing.', '짐작하지 말고 문서를 요청하는 표현입니다.', 'office'),
  ('d1_desk.it_takes_a_while', 'd1_desk', 'It takes a while.', '시간이 좀 걸려요.', '"A while" is an unclear, fairly long time.', 'a while은 꽤 긴, 정해지지 않은 시간입니다.', 'office'),
  ('d1_desk.happens_to_everybody', 'd1_desk', 'It happens to everybody.', '누구나 겪는 일이에요.', 'Makes someone feel better about a problem.', '문제를 겪는 사람을 안심시키는 말입니다.', 'small-talk'),
  ('d1_desk.get_stuck', 'd1_desk', 'Who should I ask if I get stuck?', '막히면 누구에게 물어봐야 해요?', '"Get stuck" = be unable to continue.', 'get stuck은 더 진행하지 못하게 되는 것입니다.', 'office');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('d1_desk.ping_me', 'd1_desk', 'Just ping me.', '그냥 메시지 줘요.', '"Ping" = send a quick message on chat.', 'ping은 채팅으로 짧게 연락하는 것입니다.', 'office'),
  ('d1_desk.sound_good', 'd1_desk', 'Sound good?', '괜찮죠?', 'Checks if you agree. Answer "Sounds good!"', '동의하는지 확인하는 말입니다. "Sounds good!"으로 답합니다.', 'office'),
  ('d1_lunch.sit_anywhere', 'd1_lunch', 'Sit anywhere you like.', '아무 데나 앉으세요.', 'At many diners you seat yourself.', '많은 다이너에서는 알아서 자리에 앉습니다.', 'food'),
  ('d1_lunch.how_cooked', 'd1_lunch', 'How would you like that cooked?', '어떻게 익혀 드릴까요?', 'Answer rare, medium rare, medium, medium well, or well done.', 'rare, medium rare, medium, medium well, well done 중에 답합니다.', 'food'),
                                                                                                              ('d1_lunch.for_here_or_to_go', 'd1_lunch', 'For here or to go?', '드시고 가세요, 포장하세요?', '"To go" = takeout. The British say "takeaway".', 'to go는 포장입니다. 영국에서는 takeaway라고 합니다.', 'food'),
  ('d1_lunch.right_out', 'd1_lunch', 'It''ll be right out.', '금방 나와요.', 'Your food is coming soon.', '음식이 곧 나온다는 뜻입니다.', 'food'),
  ('d1_lunch.how_was_everything', 'd1_lunch', 'How was everything?', '음식은 어떠셨어요?', 'Servers ask this near the end. "Great, thanks!" is enough.', '식사가 끝날 즈음 묻는 말입니다. "Great, thanks!"면 충분합니다.', 'food'),
  ('d1_lunch.the_check', 'd1_lunch', 'Could I get the check, please?', '계산서 주시겠어요?', 'Americans say "check"; "bill" is understood too.', '미국에서는 check라고 하고, bill도 통합니다.', 'food'),
  ('d1_lunch.keep_the_change', 'd1_lunch', 'Keep the change.', '거스름돈은 가지세요.', 'The extra becomes the tip. At a sit-down restaurant, tip 15-20%.', '남는 돈이 팁이 됩니다. 앉아서 먹는 식당에서는 15~20%를 줍니다.', 'food'),
  ('d1_lunch.hon', 'd1_lunch', 'hon', '(다정한 호칭) 자기, 손님', 'Short for "honey"; some servers call everyone this.', 'honey의 줄임말로, 누구에게나 이렇게 부르는 종업원도 있습니다.', 'food'),
  ('d1_market.find_everything', 'd1_market', 'Did you find everything okay?', '찾으시는 건 다 찾으셨어요?', 'Cashiers say this to almost everyone. "Yes, thanks" is fine.', '계산원이 거의 모든 손님에게 하는 말입니다. "Yes, thanks."면 됩니다.', 'shopping'),
  ('d1_market.rewards_card', 'd1_market', 'Do you have our rewards card?', '저희 적립 카드 있으세요?', 'Store loyalty programs give sale prices; many use your phone number.', '가게 멤버십은 할인가를 주고, 전화번호로 쓰는 경우가 많습니다.', 'shopping'),
  ('d1_market.free_to_sign_up', 'd1_market', 'Is it free to sign up?', '가입은 무료예요?', '"Sign up" = register or join.', 'sign up은 가입하다라는 뜻입니다.', 'shopping'),
  ('d1_market.punch_in', 'd1_market', 'Just punch in your phone number.', '전화번호만 누르세요.', '"Punch in" = type numbers on a keypad.', 'punch in은 키패드에 숫자를 누르는 것입니다.', 'shopping'),
  ('d1_market.paper_or_plastic', 'd1_market', 'Paper or plastic?', '종이봉투요, 비닐봉지요?', 'Some cities charge a few cents per bag. You can bring your own.', '봉투값을 몇 센트 받는 도시도 있습니다. 장바구니를 가져가도 됩니다.', 'shopping'),
  ('d1_market.insert_or_tap', 'd1_market', 'Insert or tap whenever you are ready.', '준비되시면 카드를 꽂거나 대세요.', 'Insert = chip card in the slot. Tap = contactless.', 'insert는 칩 카드를 꽂는 것, tap은 비접촉으로 대는 것입니다.', 'shopping'),
  ('d1_market.receipt_in_bag', 'd1_market', 'Could you put the receipt in the bag?', '영수증은 봉투에 넣어 주시겠어요?', 'A polite request with "Could you …?"', '"Could you …?"로 하는 정중한 부탁입니다.', 'shopping'),
  ('d1_market.have_a_good_night', 'd1_market', 'Have a good night!', '좋은 저녁 보내세요!', 'Used as a goodbye in the evening, not only at bedtime.', '잘 때만이 아니라 저녁에 헤어질 때 쓰는 인사입니다.', 'small-talk'),
  ('d2_code_review.get_a_chance', 'd2_code_review', 'Did you get a chance to look?', '혹시 볼 시간 있었어요?', 'A soft way to ask if someone has done something.', '어떤 일을 했는지 부드럽게 묻는 표현입니다.', 'office'),
  ('d2_code_review.no_rush', 'd2_code_review', 'No rush.', '급할 거 없어요.', 'Tells someone they can take their time.', '천천히 해도 된다는 말입니다.', 'office'),
  ('d2_code_review.nit', 'd2_code_review', 'It''s just a nit.', '사소한 지적이에요.', 'In code review, a "nit" is a small, picky comment.', '코드 리뷰에서 nit은 사소하고 까다로운 지적입니다.', 'office'),
  ('d2_code_review.what_do_you_suggest', 'd2_code_review', 'What do you suggest I do instead?', '대신 어떻게 하면 좋을까요?', 'Asks for advice without sounding defensive.', '방어적으로 들리지 않게 조언을 구하는 표현입니다.', 'office');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('d2_code_review.thats_fair', 'd2_code_review', 'That''s fair.', '맞는 말이에요.', 'Accepts a criticism politely.', '비판을 정중하게 받아들이는 말입니다.', 'office'),
  ('d2_code_review.push_an_update', 'd2_code_review', 'I''ll push an update.', '수정해서 올릴게요.', '"Push" = upload your code changes.', 'push는 코드 변경을 올리는 것입니다.', 'office'),
  ('d2_code_review.by_eod', 'd2_code_review', 'I''ll have it done by end of day.', '오늘 안으로 끝낼게요.', '"End of day" (EOD) = before you leave work today.', 'end of day(EOD)는 오늘 퇴근 전을 뜻합니다.', 'office'),
                                                                                                                                                                                                                                                                                                                                   ('d2_code_review.open_to_feedback', 'd2_code_review', 'Thanks for being open to feedback.', '피드백을 잘 받아 줘서 고마워요.', '"Open to" = willing to accept.', 'open to는 기꺼이 받아들인다는 뜻입니다.', 'office'),
  ('d2_reschedule.have_a_sec', 'd2_reschedule', 'Do you have a sec?', '잠깐 시간 돼요?', '"Sec" = second. A casual way to ask for a short talk.', 'sec은 second의 줄임말로, 잠깐 이야기하자는 편한 표현입니다.', 'office'),
  ('d2_reschedule.go_over', 'd2_reschedule', 'I want to go over the designs with you.', '디자인을 같이 검토하고 싶어요.', '"Go over" = review something together.', 'go over는 함께 검토하는 것입니다.', 'meeting'),
  ('d2_reschedule.does_it_work', 'd2_reschedule', 'Does one o''clock work?', '한 시 괜찮아요?', 'Asks if a time is okay for you.', '그 시간이 괜찮은지 묻는 말입니다.', 'meeting'),
  ('d2_reschedule.move_it_to', 'd2_reschedule', 'Could we move it to two?', '두 시로 옮길 수 있을까요?', 'A polite way to reschedule.', '일정을 정중하게 바꾸는 표현입니다.', 'meeting'),
  ('d2_reschedule.works_for_me', 'd2_reschedule', 'Two works for me.', '두 시 좋아요.', 'Accepts a time or plan.', '시간이나 계획을 받아들이는 말입니다.', 'meeting'),
  ('d2_reschedule.calendar_invite', 'd2_reschedule', 'I''ll send you a calendar invite.', '캘린더 초대 보낼게요.', 'Meetings are usually booked with calendar invites.', '회의는 보통 캘린더 초대로 잡습니다.', 'meeting'),
  ('d2_reschedule.something_comes_up', 'd2_reschedule', 'If something comes up …', '혹시 일이 생기면…', '"Come up" = happen unexpectedly.', 'come up은 뜻밖에 생기는 것입니다.', 'meeting'),
  ('d2_reschedule.keep_you_posted', 'd2_reschedule', 'I''ll keep you posted.', '계속 알려 드릴게요.', 'Promises to share updates.', '진행 상황을 알려 주겠다는 약속입니다.', 'office'),
  ('d2_it_laptop.file_a_ticket', 'd2_it_laptop', 'I filed a ticket about my laptop.', '노트북 문제로 티켓을 올렸어요.', 'IT problems are reported as "tickets".', 'IT 문제는 ticket으로 접수합니다.', 'office'),
  ('d2_it_laptop.keeps_freezing', 'd2_it_laptop', 'My laptop keeps freezing.', '노트북이 자꾸 멈춰요.', '"Keep + -ing" describes a problem that happens again and again.', 'keep + -ing는 계속 반복되는 문제를 말합니다.', 'office'),
  ('d2_it_laptop.tried_restarting', 'd2_it_laptop', 'Have you tried restarting it?', '재시작해 봤어요?', 'The classic first question from IT.', 'IT가 가장 먼저 하는 전형적인 질문입니다.', 'office'),
  ('d2_it_laptop.restarted_twice', 'd2_it_laptop', 'I''ve restarted it twice already.', '벌써 두 번 재시작했어요.', 'Use "already" to show you did it before now.', 'already로 이미 해 봤다는 것을 나타냅니다.', 'office'),
  ('d2_it_laptop.loaner', 'd2_it_laptop', 'Can I use a loaner in the meantime?', '그동안 대여용 기기를 써도 될까요?', '"In the meantime" = during the waiting time.', 'in the meantime은 기다리는 동안이라는 뜻입니다.', 'office'),
  ('d2_it_laptop.gigs', 'd2_it_laptop', 'eight gigs of RAM', '램 8기가', '"Gigs" is short for gigabytes.', 'gigs는 gigabytes의 줄임말입니다.', 'office'),
  ('d2_it_laptop.drop_it_off', 'd2_it_laptop', 'I can drop it off at your desk.', '자리로 갖다드릴게요.', '"Drop off" = bring something and leave it.', 'drop off는 가져다 두고 가는 것입니다.', 'office'),
  ('d3_one_on_one.settling_in', 'd3_one_on_one', 'How are you settling in?', '적응은 잘 돼요?', '"Settle in" = get used to a new place or job.', 'settle in은 새 장소나 일에 적응하는 것입니다.', 'office'),
  ('d3_one_on_one.picking_up_fast', 'd3_one_on_one', 'You''re picking things up fast.', '빨리 배우네요.', '"Pick up" can mean learn.', 'pick up은 배우다라는 뜻으로도 씁니다.', 'office'),
  ('d3_one_on_one.talk_priorities', 'd3_one_on_one', 'Let''s talk priorities.', '우선순위 얘기를 해 봐요.', 'Starts a talk about what matters most.', '무엇이 가장 중요한지 이야기를 꺼내는 말입니다.', 'meeting'),
  ('d3_one_on_one.start_with', 'd3_one_on_one', 'Which bugs should I start with?', '어떤 버그부터 시작할까요?', 'Asks where to begin.', '어디서부터 시작할지 묻는 표현입니다.', 'office');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('d3_one_on_one.walk_through', 'd3_one_on_one', 'Priya can walk you through them.', '프리야가 하나하나 설명해 줄 거예요.', '"Walk someone through" = explain step by step.', 'walk someone through는 차근차근 설명하는 것입니다.', 'office'),
  ('d3_one_on_one.more_context', 'd3_one_on_one', 'It would help to get more context.', '배경 설명을 더 들으면 도움이 될 것 같아요.', 'A polite way to ask for support.', '도움을 정중하게 요청하는 방법입니다.', 'office'),
  ('d3_one_on_one.in_the_moment', 'd3_one_on_one', 'I''d prefer to hear it right away.', '바로 듣는 게 좋아요.', '"I''d prefer" is softer than "I want".', '"I''d prefer"는 "I want"보다 부드럽습니다.', 'office'),
                                                                                                                                                                                                                   ('d3_one_on_one.keep_up', 'd3_one_on_one', 'Keep up the good work!', '계속 잘해 줘요!', 'Praise and encouragement from a manager.', '매니저의 칭찬이자 격려입니다.', 'office'),
  ('d3_lunch.grabbing_lunch', 'd3_lunch', 'We''re grabbing tacos.', '타코 사 먹으러 가요.', '"Grab" = get something quickly (food, coffee, lunch).', 'grab은 음식이나 커피를 간단히 사 오는 것입니다.', 'food'),
  ('d3_lunch.wanna_come', 'd3_lunch', 'Wanna come?', '같이 갈래요?', '"Wanna" = want to. Casual spoken English only.', 'wanna는 want to의 구어체입니다.', 'small-talk'),
  ('d3_lunch.id_love_to', 'd3_lunch', 'Sure, I''d love to.', '좋아요, 꼭 갈게요.', 'A warm way to accept an invitation.', '초대를 반갑게 받아들이는 말입니다.', 'small-talk'),
  ('d3_lunch.weekend_plans', 'd3_lunch', 'Any big plans for the weekend?', '주말에 특별한 계획 있어요?', 'Very common Wednesday-to-Friday small talk.', '수요일부터 금요일까지 아주 흔한 잡담입니다.', 'small-talk'),
  ('d3_lunch.check_out', 'd3_lunch', 'I''m thinking of checking out the park.', '공원에 한번 가 볼까 해요.', '"Check out" = go and see something new.', 'check out은 새로운 곳을 가 보는 것입니다.', 'small-talk'),
  ('d3_lunch.originally_from', 'd3_lunch', 'I''m originally from Seoul.', '원래 서울 출신이에요.', '"Originally" shows where you grew up.', 'originally는 자란 곳을 나타냅니다.', 'small-talk'),
  ('d3_lunch.liking_it_so_far', 'd3_lunch', 'How are you liking Fairview so far?', '페어뷰는 지금까지 어때요?', 'Asked to newcomers. "So far" = until now.', '새로 온 사람에게 묻는 말입니다. so far는 지금까지라는 뜻입니다.', 'small-talk'),
  ('d3_lunch.rule_of_thumb', 'd3_lunch', 'Rule of thumb: fifteen to twenty percent.', '대략적인 기준은 15~20퍼센트예요.', '"Rule of thumb" = a simple, practical guide.', 'rule of thumb은 간단하고 실용적인 기준입니다.', 'food'),
  ('d3_planning.story_points', 'd3_planning', 'story points', '스토리 포인트', 'A unit for estimating effort in agile teams, not hours.', '애자일 팀이 시간 대신 노력을 추정하는 단위입니다.', 'meeting'),
  ('d3_planning.what_does_mean', 'd3_planning', 'What does one story point mean for this team?', '이 팀에서 스토리 포인트 1은 무슨 뜻이에요?', 'Every team uses points a little differently, so it is a smart question.', '팀마다 포인트를 조금씩 다르게 써서 좋은 질문입니다.', 'meeting'),
  ('d3_planning.id_say', 'd3_planning', 'I''d say a three.', '3 정도라고 봐요.', '"I''d say …" gives an opinion or an estimate softly.', '"I''d say …"는 의견이나 추정을 부드럽게 말합니다.', 'meeting'),
  ('d3_planning.it_is', 'd3_planning', 'Three it is.', '3으로 하죠.', '"[Choice] it is" = that is decided.', '"[선택] it is"는 그걸로 정했다는 뜻입니다.', 'meeting'),
  ('d3_planning.vague', 'd3_planning', 'It''s pretty vague.', '꽤 모호해요.', '"Vague" = not clear or detailed.', 'vague는 분명하지 않거나 자세하지 않다는 뜻입니다.', 'meeting'),
  ('d3_planning.need_more_details', 'd3_planning', 'I can take it, but I''ll need more details first.', '맡을게요, 그런데 먼저 자세한 정보가 필요해요.', 'Volunteer and set a condition at the same time.', '자원하면서 동시에 조건을 거는 표현입니다.', 'meeting'),
  ('d3_planning.at_capacity', 'd3_planning', 'We''re at capacity.', '더 받을 여유가 없어요.', 'The team cannot take more work.', '팀이 더 이상 일을 받을 수 없다는 뜻입니다.', 'meeting'),
  ('d3_planning.lock_it_in', 'd3_planning', 'Let''s lock it in.', '이걸로 확정해요.', 'Makes a plan final.', '계획을 확정할 때 씁니다.', 'meeting'),
  ('d4_deadline.coming_along', 'd4_deadline', 'How''s it coming along?', '어떻게 돼 가요?', 'Asks about progress on a task.', '일의 진행 상황을 묻는 말입니다.', 'meeting'),
  ('d4_deadline.on_track', 'd4_deadline', 'Are we still on track for Friday?', '금요일 일정대로 가고 있어요?', '"On track" = going as planned.', 'on track은 계획대로 되고 있다는 뜻입니다.', 'meeting');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('d4_deadline.taking_longer', 'd4_deadline', 'It''s taking longer than I expected.', '생각보다 오래 걸리고 있어요.', 'An honest, polite way to report a delay.', '지연을 솔직하고 정중하게 알리는 표현입니다.', 'meeting'),
  ('d4_deadline.flag_early', 'd4_deadline', 'Thanks for flagging it early.', '일찍 알려 줘서 고마워요.', '"Flag" = point out a problem. US managers value early warnings.', 'flag는 문제를 알리는 것입니다. 미국 매니저들은 이른 경고를 좋아합니다.', 'meeting'),
  ('d4_deadline.slowing_down', 'd4_deadline', 'What''s slowing you down?', '뭐 때문에 늦어지고 있어요?', 'Asks about the cause of a delay.', '지연의 원인을 묻는 말입니다.', 'meeting'),
                                                                                                                                                                                                             ('d4_deadline.push_the_deadline', 'd4_deadline', 'Could we push the deadline to next Tuesday?', '마감을 다음 주 화요일로 미룰 수 있을까요?', '"Push (back)" = move to a later time.', 'push (back)은 더 늦은 때로 미루는 것입니다.', 'meeting'),
  ('d4_deadline.cut_the_scope', 'd4_deadline', 'cut the scope', '범위를 줄이다', 'Do less so you can finish on time.', '제때 끝내기 위해 할 일을 줄이는 것입니다.', 'meeting'),
  ('d4_deadline.compromise', 'd4_deadline', 'That''s a great compromise.', '좋은 절충안이에요.', 'Both sides give a little.', '양쪽이 조금씩 양보한 방안입니다.', 'meeting'),
  ('d4_benefits.paperwork', 'd4_benefits', 'new-hire paperwork', '신입 서류', 'Forms every new employee fills out.', '모든 신입 직원이 작성하는 서류입니다.', 'hr'),
  ('d4_benefits.fill_out', 'd4_benefits', 'Did you fill out your W-4?', 'W-4 작성했어요?', '"Fill out" a form = complete it.', '양식을 fill out한다는 것은 작성한다는 뜻입니다.', 'hr'),
  ('d4_benefits.withhold', 'd4_benefits', 'how much tax to withhold from each paycheck', '매 급여에서 세금을 얼마나 원천징수할지', 'US employers take income tax out of every paycheck; the W-4 sets how much.', '미국 회사는 매 급여에서 소득세를 떼고, W-4가 그 금액을 정합니다.', 'hr'),
  ('d4_benefits.deductible', 'd4_benefits', 'Which plan has the lower deductible?', '어느 플랜이 공제액이 더 낮아요?', 'You pay the deductible yourself before insurance pays.', '보험이 지급하기 전에 먼저 본인이 내는 금액입니다.', 'hr'),
  ('d4_benefits.ppo_hmo', 'd4_benefits', 'PPO or HMO', 'PPO(자유 선택형) 또는 HMO(지정 의사형)', 'HMO: cheaper, needs referrals. PPO: more choice, costs more.', 'HMO는 싸지만 의뢰서가 필요하고, PPO는 선택이 넓지만 비쌉니다.', 'hr'),
  ('d4_benefits.go_with', 'd4_benefits', 'I''ll go with the PPO.', 'PPO로 할게요.', '"Go with" = choose.', 'go with는 고르다라는 뜻입니다.', 'hr'),
  ('d4_benefits.company_match', 'd4_benefits', 'The company matches up to four percent.', '회사가 4퍼센트까지 매칭해 줘요.', 'A 401(k) is a retirement account; the match is extra money from the company.', '401(k)는 퇴직연금 계좌이고, 매칭은 회사가 더 넣어 주는 돈입니다.', 'hr'),
  ('d4_benefits.free_money', 'd4_benefits', 'That''s free money.', '공짜 돈이에요.', 'People say this about a company match.', '회사 매칭을 두고 흔히 하는 말입니다.', 'hr'),
  ('d4_pto.time_off', 'd4_pto', 'I had a quick question about time off.', '휴가에 대해 잠깐 여쭤볼 게 있어요.', '"Time off" = days you do not work. The past tense "had" sounds softer.', 'time off는 일하지 않는 날입니다. 과거형 had가 더 부드럽게 들립니다.', 'hr'),
  ('d4_pto.shoot', 'd4_pto', 'Sure, shoot.', '그럼요, 말해 봐요.', '"Shoot" = go ahead and ask.', 'shoot은 어서 물어보라는 뜻입니다.', 'small-talk'),
  ('d4_pto.pto', 'd4_pto', 'How many PTO days do we get a year?', '1년에 유급휴가가 며칠이에요?', 'PTO = paid time off (vacation days).', 'PTO는 paid time off, 즉 유급휴가입니다.', 'hr'),
  ('d4_pto.builds_up', 'd4_pto', 'It builds up every paycheck.', '급여마다 쌓여요.', 'Many US companies "accrue" PTO a little at a time.', '미국 회사 다수는 휴가를 조금씩 적립(accrue)합니다.', 'hr'),
  ('d4_pto.take_days_off', 'd4_pto', 'Could I take two days off?', '이틀 쉬어도 될까요?', '"Take … off" = not work on those days.', 'take … off는 그날 일을 쉬는 것입니다.', 'hr'),
  ('d4_pto.hr_portal', 'd4_pto', 'Put it in the HR portal.', 'HR 포털에 올려요.', 'Time off is usually requested online.', '휴가는 보통 온라인으로 신청합니다.', 'hr'),
  ('d4_pto.dont_come_in', 'd4_pto', 'If you''re sick, don''t come in.', '아프면 출근하지 마요.', '"Come in" = come to the office.', 'come in은 사무실에 나오는 것입니다.', 'hr');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('d4_pto.sick_days', 'd4_pto', 'Are sick days separate from PTO?', '병가는 유급휴가와 별도예요?', 'Some companies have one PTO bank, others keep sick days separate.', '휴가를 하나로 묶는 회사도, 병가를 따로 두는 회사도 있습니다.', 'hr'),
  ('d5_demo.youre_up', 'd5_demo', 'You''re up first.', '당신이 첫 순서예요.', '"You''re up" = it is your turn.', 'you''re up은 당신 차례라는 뜻입니다.', 'meeting'),
  ('d5_demo.share_screen', 'd5_demo', 'Let me share my screen.', '화면 공유할게요.', 'Said before showing something in a meeting.', '회의에서 무언가를 보여 주기 전에 합니다.', 'meeting'),
                                                                                                                                                                                                                                                                                                 ('d5_demo.walk_us_through', 'd5_demo', 'Walk us through what changed.', '뭐가 바뀌었는지 차근차근 설명해 줘요.', 'Asks for a step-by-step explanation.', '단계별 설명을 요청하는 말입니다.', 'meeting'),
  ('d5_demo.cut_down_on', 'd5_demo', 'That''ll cut down on support tickets.', '문의 티켓이 줄겠네요.', '"Cut down on" = reduce.', 'cut down on은 줄이다라는 뜻입니다.', 'meeting'),
  ('d5_demo.retro', 'd5_demo', 'Let''s switch to the retro.', '회고로 넘어가요.', 'A retro (retrospective) looks back at how the sprint went.', 'retro(회고)는 스프린트를 돌아보는 회의입니다.', 'meeting'),
  ('d5_demo.went_well', 'd5_demo', 'What went well?', '뭐가 잘됐어요?', 'The first question of most retros.', '대부분의 회고에서 첫 질문입니다.', 'meeting'),
  ('d5_demo.do_better', 'd5_demo', 'What could we do better?', '뭘 더 잘할 수 있을까요?', 'Invites honest but kind feedback.', '솔직하지만 친절한 피드백을 청하는 말입니다.', 'meeting'),
  ('d5_demo.acceptance_criteria', 'd5_demo', 'acceptance criteria', '인수 조건', 'The conditions a ticket must meet to be done.', '티켓이 완료되기 위해 충족해야 할 조건입니다.', 'meeting'),
  ('d5_paystub.happy_payday', 'd5_paystub', 'Happy payday!', '월급날 축하해요!', 'A cheerful greeting on payday Friday.', '급여일 금요일의 밝은 인사입니다.', 'hr'),
  ('d5_paystub.pay_stub', 'd5_paystub', 'I have a question about my pay stub.', '급여명세서에 대해 질문이 있어요.', 'The pay stub lists your pay and every deduction.', '급여명세서에는 급여와 모든 공제 항목이 나옵니다.', 'hr'),
  ('d5_paystub.gross_pay', 'd5_paystub', 'gross pay', '세전 급여(총액)', 'Your pay before taxes and deductions.', '세금과 공제 전의 급여입니다.', 'hr'),
  ('d5_paystub.federal_withholding', 'd5_paystub', 'federal withholding', '연방 소득세 원천징수', 'Income tax your employer sends to the government for you.', '회사가 당신 대신 정부에 내는 소득세입니다.', 'hr'),
  ('d5_paystub.fica', 'd5_paystub', 'FICA', '사회보장세·메디케어세', 'Social Security (6.2%) + Medicare (1.45%) = 7.65%.', '사회보장 6.2% + 메디케어 1.45% = 7.65%입니다.', 'hr'),
  ('d5_paystub.pre_tax', 'd5_paystub', 'It comes out pre-tax.', '세전으로 빠져요.', 'Pre-tax money lowers your taxable income.', '세전 공제는 과세 소득을 줄여 줍니다.', 'hr'),
  ('d5_paystub.net_pay', 'd5_paystub', 'net pay (take-home pay)', '실수령액', 'What actually arrives in your bank account.', '실제로 계좌에 들어오는 돈입니다.', 'hr'),
  ('d5_paystub.direct_deposit', 'd5_paystub', 'It goes straight to your bank by direct deposit.', '계좌 입금으로 바로 들어가요.', 'Most US employers pay by direct deposit, not paper checks.', '미국 회사 대부분은 종이 수표 대신 계좌 입금으로 급여를 줍니다.', 'hr'),
  ('d5_happy_hour.happy_hour', 'd5_happy_hour', 'happy hour', '해피아워(퇴근 후 할인 시간의 술자리)', 'Cheaper drinks after work, usually 4 to 7 p.m.; coworkers often go together.', '퇴근 후 보통 4~7시의 할인 시간으로, 동료끼리 자주 갑니다.', 'small-talk'),
  ('d5_happy_hour.you_in', 'd5_happy_hour', 'You in?', '같이 할래요?', 'Short for "Are you in?" (Will you join?)', '"Are you in?"(함께할래요?)의 줄임말입니다.', 'small-talk'),
  ('d5_happy_hour.love_to_but', 'd5_happy_hour', 'I''d love to, but I''m pretty wiped out.', '가고 싶은데 너무 지쳤어요.', '"I''d love to, but …" is the politest way to say no.', '"I''d love to, but …"는 가장 정중한 거절입니다.', 'small-talk'),
  ('d5_happy_hour.wiped_out', 'd5_happy_hour', 'wiped out', '녹초가 된', 'Very tired. "Beat" means the same.', '몹시 피곤한 상태입니다. beat도 같은 뜻입니다.', 'small-talk'),
  ('d5_happy_hour.no_pressure', 'd5_happy_hour', 'No pressure at all.', '전혀 부담 갖지 마요.', 'Tells someone they can say no.', '거절해도 된다는 뜻입니다.', 'small-talk');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('d5_happy_hour.rain_check', 'd5_happy_hour', 'Can I take a rain check?', '다음으로 미뤄도 될까요?', 'Turn down an invitation now but accept it for later.', '지금은 거절하지만 다음에 받겠다는 표현입니다.', 'small-talk'),
  ('d5_happy_hour.holding_you_to_that', 'd5_happy_hour', 'I''m holding you to that!', '그 약속 지켜야 해요!', 'Playfully says you will remember the promise.', '약속을 기억하겠다고 장난스럽게 말하는 표현입니다.', 'small-talk'),
  ('d5_happy_hour.means_a_lot', 'd5_happy_hour', 'That means a lot.', '그 말 정말 힘이 돼요.', 'A warm reply to a compliment.', '칭찬에 대한 따뜻한 대답입니다.', 'small-talk');
